    <div id="status-container"></div>
    <script>
        const rawData = String.raw`$1`;
        const ICONS = { '着装': `<i class="fa-solid fa-tag"></i>`, '姿态': `<i class="fa-solid fa-wand-magic-sparkles"></i>`, '位置': `<i class="fa-solid fa-location-dot"></i>` };
        function getThemeClass(charName) { if (charName.includes('周言')) return 'theme-zhouyan'; if (charName.includes('沈锡元')) return 'theme-shenxiyuan'; return 'theme-other'; }
        function switchTab(tabContainer, panelContainer, index) { 
            tabContainer.querySelectorAll('.tab-button').forEach(btn => btn.classList.remove('active')); 
            tabContainer.querySelectorAll('.tab-button')[index].classList.add('active'); 
            panelContainer.querySelectorAll('.char-panel').forEach(panel => panel.classList.remove('active')); 
            panelContainer.querySelectorAll('.char-panel')[index].classList.add('active'); 
        }

        function parseAndRender() {
            const container = document.getElementById('status-container'); if (!container) return;
            const envRegex = /<环境>([\s\S]+?)<\/环境>/; 
            const charRegex = /<([^>]+?)>\s*着装：([\s\S]+?)\s*姿态：([\s\S]+?)\s*位置：([\s\S]+?)\s*关系：([\s\S]+?)\s*心声：([\s\S]+?)\s*<\/\1>/g;
            const envMatch = rawData.match(envRegex); 
            const environment = envMatch ? envMatch[1].trim() : '环境信息缺失';

            const keyMap = { '着装': 'dressing', '姿态': 'pose', '位置': 'location' };

            let charArray = []; 
            let charMatch; 
            while ((charMatch = charRegex.exec(rawData)) !== null) { 
                const [_, name, dressing, pose, location, relation, thought] = charMatch.map(s => s.trim()); 
                charArray.push({ name, dressing, pose, location, relation, thought }); 
            }
            if (charArray.length === 0) return;

            let tabsHTML = charArray.map((char, index) => `<button class="tab-button ${index === 0 ? 'active' : ''}">${char.name}</button>`).join('');

            let panelsHTML = charArray.map((char, index) => {
                const themeClass = getThemeClass(char.name);

                let detailsListHTML = Object.entries(ICONS).map(([key, iconHtml]) => {
                    const value = char[keyMap[key]];
                    return `
                    <li class="detail-item">
                        <div class="detail-icon">${iconHtml}</div>
                        <div class="detail-content">
                             <span class="detail-label ${themeClass}">${key}：</span>
                             <span class="detail-value">${value || '（未提供）'}</span>
                        </div>
                    </li>`;
                }).join('');

                return `
                <div class="char-panel ${themeClass} ${index === 0 ? 'active' : ''}">
                    <div class="relation-bar ${themeClass}">
                        ${`&nbsp;✧&nbsp;${char.relation}&nbsp;✧&nbsp;`} 
                    </div>
                    <ul class="char-details">
                       ${detailsListHTML}
                    </ul>
                    <p class="char-quote ${themeClass}">${char.thought}</p>
                </div>`;
            }).join('');

            const initialThemeClass = getThemeClass(charArray[0].name); 

            const finalHTML = `<div class="status-wrapper"><details><summary class="status-summary"><span>${environment}</span></summary><div class="status-content"><div class="char-tabs ${initialThemeClass}">${tabsHTML}</div><div class="char-panels">${panelsHTML}</div></div></details></div>`; 

            container.innerHTML = finalHTML;

            const tabContainer = container.querySelector('.char-tabs'); 
            container.querySelectorAll('.tab-button').forEach((btn, index) => { 
                btn.onclick = () => { 
                    const activeTheme = getThemeClass(charArray[index].name); 
                    tabContainer.className = 'char-tabs ' + activeTheme; 
                    switchTab(tabContainer, container.querySelector('.char-panels'), index); 
                }; 
            });
        }
        parseAndRender();
    </script>
</body>
</html>
