    </div>
    <script>
    const StickerStorageManager = {
        LOREBOOK_NAME: "关于霖大附中不得不说的那些事",
        ENTRY_COMMENT: "媒体与表情包_StickerData",
        URL_PREFIX: "https://files.catbox.moe/", 
        TAG_REGEX: /<表情包>([\s\S]*?)<\/表情包>/,

        async getEntry() {
            try {
                // console.log(`[手机_NEW DEBUG] 1. 开始查找世界书: "${this.LOREBOOK_NAME}"`);
                const allEntries = await getLorebookEntries(this.LOREBOOK_NAME);

                // console.log('[手机_NEW DEBUG] 2. API返回的所有条目:', JSON.stringify(allEntries, null, 2)); 

                const targetEntry = allEntries.find(entry => entry.comment === this.ENTRY_COMMENT);

                if (targetEntry) {
                    // console.log(`[手机_NEW DEBUG] 3. 成功找到目标条目! Comment: "${targetEntry.comment}", UID: ${targetEntry.uid}`);
                } else {
                    // console.error(`[手机_NEW DEBUG] 3. 错误: 在返回的条目中，没能找到备注为 "${this.ENTRY_COMMENT}" 的条目!`);
                } 

                return targetEntry;
            } catch (err) {
                // console.error('[手机_NEW DEBUG] getEntry() 过程出错:', err);
                return null;
            }
        },

        async saveStickers(stickers) {
            const entryToUpdate = await this.getEntry();
            if (!entryToUpdate) {
                // console.error("【手机_NEW】错误：找不到世界书条目，无法保存。请检查日志确认查找过程。");
                return false;
            } 

            // console.log(`[手机_NEW DEBUG] 4. 准备使用 UID: ${entryToUpdate.uid} 来更新内容。`);

            const newContentBlock = `<表情包>\n${JSON.stringify(stickers, null, 2)}\n</表情包>`;
            let finalContent;
            if (this.TAG_REGEX.test(entryToUpdate.content)) {
                finalContent = entryToUpdate.content.replace(this.TAG_REGEX, newContentBlock);
            } else {
                finalContent = entryToUpdate.content + "\n\n" + newContentBlock;
            }

            try {
                await setLorebookEntries(this.LOREBOOK_NAME, [{ uid: entryToUpdate.uid, content: finalContent }]);
                // console.log(`[手机_NEW DEBUG] 5. 成功调用 setLorebookEntries 更新 UID: ${entryToUpdate.uid}。操作完成。`);
                return true;
            } catch (err) {
                // console.error(`[手机_NEW DEBUG] 5. 调用 setLorebookEntries 更新 UID: ${entryToUpdate.uid} 失败!`, err);
                return false;
            }
        },

        async getStickers() { const e = await this.getEntry(); if (!e || !e.content) return {}; const t = e.content.match(this.TAG_REGEX); if (!t || !t[1]) return {}; try { return JSON.parse(t[1].trim()); } catch (e) { return {}; } },
        async addSticker(e, t) { const s = await this.getStickers(); s[e] = t; return this.saveStickers(s); },
        async deleteSticker(e) { const t = await this.getStickers(); delete t[e]; return this.saveStickers(t); }
    };

    setTimeout(function() {
        document.querySelectorAll('.phone-container:not([data-initialized])').forEach(async container => {
            container.dataset.initialized = 'true';

            let stagedMessages = [];
            const chatContainer = container.querySelector('.chat-container');
            const chatMessagesContainer = container.querySelector('.chat-messages');
            const stagedMessagesDisplay = container.querySelector('#staged-messages-container');
            const textInput = container.querySelector('.input-field');
            const stageBtn = container.querySelector('.stage-btn');
            const realSendBtn = container.querySelector('.real-send-btn');
            const plusBtn = container.querySelector('.plus-btn');
            const actionMenu = container.querySelector('.action-menu-container');
            const chatName = container.querySelector('.chat-header h2').textContent;

            function updateStatusTime() {
                const now = new Date();
                const h = now.getHours();
                const m = now.getMinutes();
                const timeEl = container.querySelector('.status-time');
                if(timeEl) timeEl.textContent = `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
            }

            // Modal Elements
            const stickerMenuBtn = container.querySelector('.sticker-menu-btn');
            const stickerPanel = container.querySelector('.sticker-panel');
            const imageMenuBtn = container.querySelector('.image-menu-btn');
            const imageModalOverlay = chatContainer.querySelector('.image-modal-overlay');
            const transferMenuBtn = container.querySelector('.transfer-menu-btn');
            const transferModalOverlay = chatContainer.querySelector('.transfer-modal-overlay');
            const voiceMenuBtn = container.querySelector('.voice-menu-btn');
            const voiceModalOverlay = container.querySelector('.voice-modal-overlay');
            const callMenuBtn = container.querySelector('.call-menu-btn');
            const callModalOverlay = container.querySelector('.call-modal-overlay');
            const videoMenuBtn = container.querySelector('.video-menu-btn');
            const videoCallModalOverlay = container.querySelector('.video-call-modal-overlay');
            const locationMenuBtn = container.querySelector('.location-menu-btn');
            const locationModalOverlay = container.querySelector('.location-modal-overlay');
            const pokeMenuBtn = container.querySelector('.poke-menu-btn');
            const allModals = [imageModalOverlay, transferModalOverlay, voiceModalOverlay, callModalOverlay, videoCallModalOverlay, locationModalOverlay];

            const stateStorage = document.createElement('div');
            stateStorage.id = `staged-state-${container.id || Math.random().toString(36).substring(2)}`;
            stateStorage.style.display = 'none'; document.body.appendChild(stateStorage);

            function updateRealSendBtnVisibility() { realSendBtn.style.display = stagedMessages.length > 0 ? 'block' : 'none'; }
            function persistState() { stateStorage.textContent = JSON.stringify(stagedMessages); updateRealSendBtnVisibility(); }
            function restoreState() { if (stateStorage.textContent) { try { stagedMessages = JSON.parse(stateStorage.textContent); } catch (e) { stagedMessages = []; } } renderAllStagedMessages(); }
            function stageMessage(type, content) { stagedMessages.push({ type, content }); persistState(); renderAllStagedMessages(); }

            function renderStagedMessage(msg, index) {
                const messageEl = document.createElement('div');
                messageEl.dataset.index = index;
                let messageContentHTML = '';
                let messageClasses = 'message message-staged';

                const voiceIconSVG = `<svg class="voice-icon-svg" viewBox="0 0 24 24"><path d="M8,18.5C8,18.5 12,15.5 12,12C12,8.5 8,5.5 8,5.5" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" fill="none"/><path d="M12,20.5C12,20.5 16,16.5 16,12C16,7.5 12,3.5 12,3.5" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" fill="none" style="opacity: 0.6;"/><path d="M4,15.5C4,15.5 8,13.5 8,12C8,10.5 4,8.5 4,8.5" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" fill="none" style="opacity: 0.8;"/></svg>`;

                if (msg.type === 'text') { 
                    messageClasses += ' sent';
                    messageContentHTML = `<div class="avatar user_avatar"></div><div class="message-wrapper"><button class="delete-staged-msg-btn" data-index="${index}">×</button><div class="message-content">${msg.content}</div></div>`;
                } else if (msg.type === 'sticker') { 
                    messageClasses += ' sent';
                    messageContentHTML = `<div class="avatar user_avatar"></div><div class="message-wrapper"><button class="delete-staged-msg-btn" data-index="${index}">×</button><div class="message-content"><img src="${msg.content.url}" class="sticker-preview" alt="${msg.content.name}" title="${msg.content.name}"></div></div>`;
                } else if (msg.type === 'image') { 
                    messageClasses += ' sent';
                    const randomBg = `https://source.unsplash.com/random/120x120?sig=${Math.random()}`;
                    const imageCardHTML = `<div class="image-card show-desc" style="background-image: url('${randomBg}');"><div class="image-card-desc"><p>${msg.content}</p></div></div>`;
                    messageContentHTML = `<div class="avatar user_avatar"></div><div class="message-wrapper"><button class="delete-staged-msg-btn" data-index="${index}">×</button>${imageCardHTML}</div>`;
                } else if (msg.type === 'transfer') { 
                    messageClasses += ' sent';
                    const noteHTML = msg.content.note ? `<div class="note-container">${msg.content.note}</div>` : '';
                    const transferCardHTML = `<div class="transfer-card"><div class="transfer-header"><p>转账给 ${msg.content.to}</p></div><div class="transfer-body"><p class="amount">￥${msg.content.amount}</p>${noteHTML}</div></div>`;
                    messageContentHTML = `<div class="avatar user_avatar"></div><div class="message-wrapper"><button class="delete-staged-msg-btn" data-index="${index}">×</button>${transferCardHTML}</div>`;
                } else if (msg.type === 'voice') {
                    messageClasses += ' sent';
                    const cleanedContent = msg.content.replace(/[（\(][\s\S]*?[）\)]/g, '').trim();
                    const duration = Math.max(1, Math.ceil(cleanedContent.length / 6));
                    const voiceHTML = `<div class="message-content"><div class="voice-message-container"><button class="voice-bar"><span class="voice-duration">${duration}\"</span>${voiceIconSVG}</button><div class="voice-transcription">${msg.content}</div></div></div>`;
                    messageContentHTML = `<div class="avatar user_avatar"></div><div class="message-wrapper"><button class="delete-staged-msg-btn" data-index="${index}">×</button>${voiceHTML}</div>`;
                } else if (msg.type === 'location') {
                    messageClasses += ' sent';
                    const locationCardHTML = `<div class="location-card"><div class="location-map"><i class="fas fa-map-marker-alt"></i></div><div class="location-info"><p>${msg.content}</p></div></div>`;
                    const locationHTML = `<div class="message-content has-location-card">${locationCardHTML}</div>`;
                    messageContentHTML = `<div class="avatar user_avatar"></div><div class="message-wrapper"><button class="delete-staged-msg-btn" data-index="${index}">×</button>${locationHTML}</div>`;
                } else if (msg.type === 'poke') {
                    messageClasses += ' system-staged';
                    messageContentHTML = `<div class="message-wrapper"><button class="delete-staged-msg-btn" data-index="${index}">×</button><div class="system-message-content">${msg.content}</div></div>`;
                }

                messageEl.className = messageClasses;
                messageEl.innerHTML = messageContentHTML;
                stagedMessagesDisplay.appendChild(messageEl);
            }

            function renderAllStagedMessages() { stagedMessagesDisplay.innerHTML = ''; stagedMessages.forEach(renderStagedMessage); chatMessagesContainer.scrollTop = chatMessagesContainer.scrollHeight; updateRealSendBtnVisibility(); }
            function stageUserTextMessage() { const text = textInput.value.trim(); if (text) { stageMessage('text', text); textInput.value = ''; textInput.focus(); } }

            function sendStagedMessages(suffix = '') {
                 if ((stagedMessages.length > 0 || suffix) && typeof triggerSlash === 'function') {
                    let messageBlock = stagedMessages.map(msg => {
                        if (msg.type === 'image') return `<tp>${msg.content}</tp>`;
                        if (msg.type === 'sticker') return `<bqb>${msg.content.name}</bqb>`;
                        if (msg.type === 'transfer') return `user转账给${msg.content.to}:￥${msg.content.amount}|${msg.content.note || ''}`;
                        if (msg.type === 'voice') return `<yy>${msg.content}</yy>`;
                        if (msg.type === 'location') return `<dw>${msg.content}</dw>`;
                        if (msg.type === 'poke') return `<戳一戳>${msg.content}</戳一戳>`;
                        return msg.content;
                    }).join('\n');
                    if (suffix) {
                        messageBlock = messageBlock ? `${messageBlock}\n${suffix}` : suffix;
                    }
                    if (!messageBlock) return false;
                    const commandText = `线上私聊|目标:${chatName}\n内容:${messageBlock}`;
                    stagedMessages = []; persistState(); stagedMessagesDisplay.innerHTML = '';
                    triggerSlash(`/send ${commandText.replace(/\|/g, '\\|')}|/trigger`);
                    return true;
                }
                return false;
            }

            stageBtn.addEventListener('click', stageUserTextMessage);
            textInput.addEventListener('keypress', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); stageUserTextMessage(); } });

            stagedMessagesDisplay.addEventListener('click', (e) => {
                const voiceBar = e.target.closest('.voice-bar');
                if (voiceBar) { const container = voiceBar.closest('.voice-message-container'); if (container) container.classList.toggle('active'); e.stopPropagation(); return; }

                if (e.target.classList.contains('delete-staged-msg-btn')) { 
                    const index = parseInt(e.target.dataset.index, 10); 
                    stagedMessages.splice(index, 1); 
                    persistState(); 
                    renderAllStagedMessages(); 
                    return; 
                }

                const clickedStagedMsg = e.target.closest('.message-staged');
                if (clickedStagedMsg) {
