            transition: transform 0.2s, background-color 0.2s;
            user-select: none;
        }
        .poke-bubble:hover {
            background-color: #ccc;
            transform: scale(1.05);
        }
        .poke-bubble i {
            margin-right: 6px;
        }
        .message:has(.poke-bubble) {
            margin-bottom: 16px;
        }
        .phone-container.is-shaking {
            animation: shake 0.5s cubic-bezier(.36,.07,.19,.97) both;
        }
        @keyframes shake {
            10%, 90% { transform: translate3d(-1px, 0, 0); }
            20%, 80% { transform: translate3d(2px, 0, 0); }
            30%, 50%, 70% { transform: translate3d(-3px, 0, 0); }
            40%, 60% { transform: translate3d(3px, 0, 0); }
        }
    </style>
</head>
<body>
    <div class="phone-container">
        <div class="phone-notch"><div class="notch-sensor"></div><div class="notch-camera"></div><div class="notch-speaker"></div><div class="notch-sensor"></div></div>
        <div class="chat-container">
            <div class="status-bar">
                <span class="status-time">12:00</span>
                <div class="status-bar-right">
                    <i class="fas fa-signal"></i>
                    <i class="fas fa-wifi"></i>
                    <i class="fas fa-battery-full"></i>
                </div>
            </div>
            <div class="chat-header">
                <h2>$1</h2>
                <div class="header-icons"><svg class="real-send-btn" viewBox="0 0 24 24"><path fill="currentColor" d="M9 16.2L4.8 12l-1.4 1.4L9 19 21 7l-1.4-1.4L9 16.2z"/></svg></div>
            </div>
            <div class="chat-messages">
                $2
                <div id="staged-messages-container"></div>
            </div>
            <div class="chat-input">
                <button class="action-btn plus-btn"><i class="fas fa-plus-circle"></i></button>
                <input type="text" class="input-field" placeholder="输入聊天内容...">
                <button class="stage-btn"><svg viewBox="0 0 24 24" width="20" height="20"><path fill="currentColor" d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg></button>
            </div>
            <div class="action-menu-container">
                <button class="action-menu-button sticker-menu-btn"><span class="action-menu-icon"><i class="far fa-grin-wink"></i></span></button>
                <button class="action-menu-button image-menu-btn"><span class="action-menu-icon"><i class="far fa-image"></i></span></button>
                <button class="action-menu-button voice-menu-btn"><span class="action-menu-icon"><i class="fas fa-microphone"></i></span></button>
                <button class="action-menu-button location-menu-btn"><span class="action-menu-icon"><i class="fas fa-map-marker-alt"></i></span></button>
                <!-- New Row for Group Video and Placeholders -->
                <button class="action-menu-button group-video-menu-btn"><span class="action-menu-icon"><i class="fas fa-video"></i></span></button>
                <button class="action-menu-button"><span class="action-menu-icon"><i class="fas fa-times"></i></span></button>
                <button class="action-menu-button"><span class="action-menu-icon"><i class="fas fa-times"></i></span></button>
                <button class="action-menu-button"><span class="action-menu-icon"><i class="fas fa-times"></i></span></button>
            </div>
            <div class="sticker-panel">
                <div class="sticker-tabs">
                    <div class="sticker-tab active" data-tab="stickers">表情包</div>
                    <div class="sticker-tab" data-tab="add">添加</div>
                </div>
                <div class="sticker-grid active" id="all-stickers"></div>
                <div class="sticker-add-panel" id="add-sticker-panel">
                    <div class="sticker-add-form">
                        <input type="text" class="sticker-add-input" id="sticker-url-input" placeholder="catbox文件名（例如：fcw3mi.gif）">
                        <input type="text" class="sticker-add-input" id="sticker-name-input" placeholder="表情描述（例如：开心）">
                        <div class="sticker-add-preview" id="sticker-preview"></div>
                        <div class="sticker-add-buttons">
                            <button class="sticker-add-button cancel" id="cancel-add-sticker">取消</button>
                            <button class="sticker-add-button" id="add-sticker-btn">添加表情</button>
                        </div>
                    </div>
                </div>
            </div>
             <!-- Modals -->
            <div class="modal-overlay image-modal-overlay">
                <div class="modal-box image-modal">
                    <h3>输入图片描述</h3>
                    <textarea class="modal-textarea image-modal-textarea" placeholder="例如：一张猫猫在夕阳下打哈欠的照片"></textarea>
                    <div class="modal-buttons">
                        <button class="modal-button confirm">确认</button>
                        <button class="modal-button cancel">取消</button>
                    </div>
                </div>
            </div>
            <div class="modal-overlay voice-modal-overlay">
                <div class="modal-box voice-modal">
                    <h3>输入语音内容描述</h3>
                    <textarea class="modal-textarea voice-modal-textarea" placeholder="例如：（语气平静）明天再说吧。"></textarea>
                    <div class="modal-buttons">
                        <button class="modal-button confirm">确认</button>
                        <button class="modal-button cancel">取消</button>
                    </div>
                </div>
            </div>
            <div class="modal-overlay location-modal-overlay">
                <div class="modal-box location-modal">
                    <h3>分享位置</h3>
                    <input type="text" class="modal-input location-modal-input" placeholder="例如：霖大附中南门">
                    <div class="modal-buttons">
                        <button class="modal-button confirm">确认</button>
                        <button class="modal-button cancel">取消</button>
                    </div>
                </div>
            </div>
             <!-- New Group Video Call Modal -->
             <div class="modal-overlay group-video-call-modal-overlay">
                <div class="modal-box group-video-call-modal">
                    <h3>发起群视频</h3>
                    <p style="text-align:center; font-size: 13px; color: #888;">将同时发送所有暂存信息。</p>
                    <p style="text-align:center; font-size: 13px; color: #888;">默认向全体群成员发起通话</p>
                    <div class="modal-buttons">
                        <button class="modal-button confirm">确认</button>
                        <button class="modal-button cancel">取消</button>
                    </div>
                </div>
            </div>
        </div>
    </div>
    <script>
    const StickerStorageManager = {
        LOREBOOK_NAME: "关于霖大附中不得不说的那些事", ENTRY_COMMENT: "媒体与表情包_StickerData", URL_PREFIX: "https://files.catbox.moe/", TAG_REGEX: /<表情包>([\s\S]*?)<\/表情包>/,
        async getEntry() { try { const e = await getLorebookEntries(this.LOREBOOK_NAME); return e.find(e => e.comment === this.ENTRY_COMMENT); } catch (e) { return null; } },
        async getStickers() { const e = await this.getEntry(); if (!e || !e.content) return {}; const t = e.content.match(this.TAG_REGEX); if (!t || !t[1]) return {}; try { return JSON.parse(t[1].trim()); } catch (e) { return {}; } },
        async saveStickers(e) { const t = await this.getEntry(); if (!t) return false; const s = `<表情包>\n${JSON.stringify(e, null, 2)}\n</表情包>`; let n; if (this.TAG_REGEX.test(t.content)) { n = t.content.replace(this.TAG_REGEX, s); } else { n = t.content + "\n\n" + s; } try { await setLorebookEntries(this.LOREBOOK_NAME, [{ uid: t.uid, content: n }]); return true; } catch (e) { return false; } },
        async addSticker(e, t) { const s = await this.getStickers(); s[e] = t; return this.saveStickers(s); },
        async deleteSticker(e) { const t = await this.getStickers(); delete t[e]; return this.saveStickers(t); }
    };

    setTimeout(function() {
        document.querySelectorAll('.phone-container:not([data-initialized])').forEach(container => {
            container.dataset.initialized = 'true';
            let stagedMessages = [];

            const chatContainer = container.querySelector('.chat-container');
            const chatMessagesContainer = container.querySelector('.chat-messages');
            const stagedMessagesDisplay = container.querySelector('#staged-messages-container');
            const textInput = container.querySelector('.input-field');
            const stageBtn = container.querySelector('.stage-btn');
            const realSendBtn = container.querySelector('.real-send-btn');
            const plusBtn = container.querySelector('.plus-btn');
            const actionMenu = container.querySelector('.action-menu-container');
            const chatName = container.querySelector('.chat-header h2').textContent;

            const stickerMenuBtn = container.querySelector('.sticker-menu-btn');
            const stickerPanel = container.querySelector('.sticker-panel');

            // Modal Elements
            const imageMenuBtn = container.querySelector('.image-menu-btn');
            const imageModalOverlay = chatContainer.querySelector('.image-modal-overlay');
            const voiceMenuBtn = container.querySelector('.voice-menu-btn');
            const voiceModalOverlay = container.querySelector('.voice-modal-overlay');
            const locationMenuBtn = container.querySelector('.location-menu-btn');
            const locationModalOverlay = container.querySelector('.location-modal-overlay');
            const groupVideoMenuBtn = container.querySelector('.group-video-menu-btn');
            const groupVideoCallModalOverlay = container.querySelector('.group-video-call-modal-overlay');
            const allModals = [imageModalOverlay, voiceModalOverlay, locationModalOverlay, groupVideoCallModalOverlay];

            function updateStatusTime() {
                const now = new Date();
                const h = now.getHours();
                const m = now.getMinutes();
                const timeEl = container.querySelector('.status-time');
                if(timeEl) timeEl.textContent = `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
            }

            const stateStorage = document.createElement('div');
            stateStorage.id = `staged-state-group-${container.id || Math.random().toString(36).substring(2)}`;
            stateStorage.style.display = 'none'; document.body.appendChild(stateStorage);

            function updateRealSendBtnVisibility() { realSendBtn.style.display = stagedMessages.length > 0 ? 'block' : 'none'; }
            function persistState() { stateStorage.textContent = JSON.stringify(stagedMessages); updateRealSendBtnVisibility(); }
            function restoreState() { if (stateStorage.textContent) { try { stagedMessages = JSON.parse(stateStorage.textContent); } catch (e) { stagedMessages = []; } } renderAllStagedMessages(); }
            function stageMessage(type, content) { stagedMessages.push({ type, content }); persistState(); renderAllStagedMessages(); }

            function renderStagedMessage(msg, index) {
                const messageEl = document.createElement('div');
                messageEl.dataset.index = index;
                let cardHTML = '';
                let messageClasses = 'message message-staged sent';
                let wrapperContent = '';

                if (msg.type === 'image') {
                    const randomBg = `https://source.unsplash.com/random/120x120?sig=${Math.random()}`;
                    cardHTML = `<div class=\"image-card show-desc\" style=\"background-image: url('${randomBg}');\"><div class=\"image-card-desc\"><p>${msg.content.replace(/\n/g, '<br>')}</p></div></div>`;
                    wrapperContent = `<button class=\"delete-staged-msg-btn\" data-index=\"${index}\">×</button>${cardHTML}`;
                } else {
                    let contentHTML = '';
                    if (msg.type === 'text') {
                        contentHTML = msg.content;
                    } else if (msg.type === 'sticker') {
                        contentHTML = `<img src=\"${msg.content.url}\" class=\"sticker-preview\" alt=\"${msg.content.name}\" title=\"${msg.content.name}\">`;
                    } else if (msg.type === 'voice') {
                        const voiceIconSVG = `<svg class=\"voice-icon-svg\" viewBox=\"0 0 24 24\"><path d=\"M8,18.5C8,18.5 12,15.5 12,12C12,8.5 8,5.5 8,5.5\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\"/><path d=\"M12,20.5C12,20.5 16,16.5 16,12C16,7.5 12,3.5 12,3.5\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\" style=\"opacity: 0.6;\"/><path d=\"M4,15.5C4,15.5 8,13.5 8,12C8,10.5 4,8.5 4,8.5\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\" style=\"opacity: 0.8;\"/></svg>`;
                        const cleanedContent = msg.content.replace(/[（\(][\s\S]*?[）\)]/g, '').trim();
                        const duration = Math.max(1, Math.ceil(cleanedContent.length / 6));
                        contentHTML = `<div class=\"voice-message-container\"><button class=\"voice-bar\"><span class=\"voice-duration\">${duration}\"</span>${voiceIconSVG}</button><div class=\"voice-transcription\">${msg.content}</div></div>`;
                    } else if (msg.type === 'location') {
                        cardHTML = `<div class=\"location-card\"><div class=\"location-map\"><i class=\"fas fa-map-marker-alt\"></i></div><div class=\"location-info\"><p>${msg.content}</p></div></div>`;
                        wrapperContent = `<button class=\"delete-staged-msg-btn\" data-index=\"${index}\">×</button>${cardHTML}`;
                        messageEl.className = messageClasses;
                        messageEl.innerHTML = `<div class=\"user_avatar avatar\"></div><div class=\"message-wrapper\">${wrapperContent}</div>`;
                        stagedMessagesDisplay.appendChild(messageEl);
                        return;
                    }
                    cardHTML = `<div class=\"message-content\">${contentHTML}</div>`;
                    wrapperContent = `<button class=\"delete-staged-msg-btn\" data-index=\"${index}\">×</button>${cardHTML}`;
                }

                messageEl.className = messageClasses;
                messageEl.innerHTML = `<div class=\"user_avatar avatar\"></div><div class=\"message-wrapper\">${wrapperContent}</div>`;
                stagedMessagesDisplay.appendChild(messageEl);
            }

            function renderAllStagedMessages() { stagedMessagesDisplay.innerHTML = ''; stagedMessages.forEach(renderStagedMessage); chatMessagesContainer.scrollTop = chatMessagesContainer.scrollHeight; updateRealSendBtnVisibility(); }
            function stageUserTextMessage() { const text = textInput.value.trim(); if (text) { stageMessage('text', text); textInput.value = ''; textInput.focus(); } }

            // MODIFIED: This function now accepts an optional suffix to append to the message block
            function sendStagedMessages(suffix = '') {
                if ((stagedMessages.length > 0 || suffix) && typeof triggerSlash === 'function') {
                    let messageBlock = stagedMessages.map(msg => {
                        if (msg.type === 'image') return `<tp>${msg.content}</tp>`;
                        if (msg.type === 'sticker') return `<bqb>${msg.content.name}</bqb>`;
                        if (msg.type === 'voice') return `<yy>${msg.content}</yy>`;
                        if (msg.type === 'location') return `<dw>${msg.content}</dw>`;
                        return msg.content;
                    }).join('\n');

                    if (suffix) {
                        messageBlock = messageBlock ? `${messageBlock}\n${suffix}` : suffix;
                    }

                    if (!messageBlock) return false;
                    const commandText = `线上群聊|目标:${chatName}\n内容:${messageBlock}`;
                    stagedMessages = []; persistState(); stagedMessagesDisplay.innerHTML = '';
                    triggerSlash(`/send ${commandText.replace(/\|/g, '\\|')}|/trigger`);
                    return true;
                }
                return false;
            }

            restoreState();

            const ContentRenderer = {
                stickerMap: null, observer: null,
                init(targetNode) { this.loadStickers().then(() => { this.renderExisting(targetNode); this.startObserver(targetNode); }); },
                async loadStickers() { this.stickerMap = await StickerStorageManager.getStickers(); },
                renderNode(node) {
                    if (node.nodeType === Node.ELEMENT_NODE && node.classList.contains('message-content')) {
                        const imageRenderRegex = /<tp>([\s\S]*?)<\/tp>/g; const bqbRegex = /<bqb>(.*?)<\/bqb>/g; const voiceRegex = /<yy>([\s\S]*?)<\/yy>/g; const locationRegex = /<dw>(.*?)<\/dw>/g; const voiceIconSVG = `<svg class=\"voice-icon-svg\" viewBox=\"0 0 24 24\"><path d=\"M8,18.5C8,18.5 12,15.5 12,12C12,8.5 8,5.5 8,5.5\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\"/><path d=\"M12,20.5C12,20.5 16,16.5 16,12C16,7.5 12,3.5 12,3.5\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\" style=\"opacity: 0.6;\"/><path d=\"M4,15.5C4,15.5 8,13.5 8,12C8,10.5 4,8.5 4,8.5\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\" style=\"opacity: 0.8;\"/></svg>`;
                        let newHTML = node.innerHTML;
                        if (/^\s*<tp>[\s\S]*?<\/tp>\s*$/.test(newHTML.trim())) {
                            node.classList.add('has-image-card');
                        }
                        newHTML = newHTML.replace(imageRenderRegex, (match, imageDesc) => { const desc = imageDesc.trim().replace(/\n/g, '<br>'); const randomBg = `https://source.unsplash.com/random/120x120?sig=${Math.random()}`; return `<div class=\"image-card\" style=\"background-image: url('${randomBg}');\"><div class=\"image-card-desc\"><p>${desc}</p></div></div>`; });
                        newHTML = newHTML.replace(bqbRegex, (match, stickerName) => { const filename = this.stickerMap[stickerName]; return filename ? `<img src=\"${StickerStorageManager.URL_PREFIX + filename}\" class=\"sticker-preview\" alt=\"${stickerName}\" title=\"${stickerName}\">` : match; }); 
                        newHTML = newHTML.replace(voiceRegex, (match, voiceContent) => { const isSent = node.closest('.message.sent'); const contentText = voiceContent.trim(); const cleanedContentText = contentText.replace(/[（\(][\s\S]*?[）\)]/g, '').trim(); const duration = Math.max(1, Math.ceil(cleanedContentText.length / 6)); const durationSpan = `<span class=\"voice-duration\">${duration}\"</span>`; const barContent = isSent ? `${durationSpan}${voiceIconSVG}` : `${voiceIconSVG}${durationSpan}`; return `<div class=\"voice-message-container\"><button class=\"voice-bar\">${barContent}</button><div class=\"voice-transcription\">${contentText}</div></div>`; });
                        if (locationRegex.test(newHTML)) { node.classList.add('has-location-card'); newHTML = newHTML.replace(locationRegex, (match, locationText) => { return `<div class=\"location-card\"><div class=\"location-map\"><i class=\"fas fa-map-marker-alt\"></i></div><div class=\"location-info\"><p>${locationText.trim()}</p></div></div>`; }); }
                        node.innerHTML = newHTML;
                    }
                },
                renderExisting(targetNode) { targetNode.querySelectorAll('.message-content').forEach(content => this.renderNode(content)); },
                startObserver(targetNode) { this.observer = new MutationObserver(mutations => { mutations.forEach(mutation => { mutation.addedNodes.forEach(addedNode => { if (addedNode.nodeType === Node.ELEMENT_NODE) { if (addedNode.classList.contains('message')) { const content = addedNode.querySelector('.message-content'); if (content) this.renderNode(content); } else if (addedNode.querySelectorAll) { addedNode.querySelectorAll('.message-content').forEach(content => this.renderNode(content)); } } }); }); }); this.observer.observe(targetNode, { childList: true, subtree: true }); }
            };
            ContentRenderer.init(chatMessagesContainer);
            chatMessagesContainer.scrollTop = 0;

            chatMessagesContainer.addEventListener('click', (e) => {
                const imageCard = e.target.closest('.image-card'); if (imageCard) { imageCard.classList.toggle('show-desc'); return; }
                const voiceBar = e.target.closest('.voice-bar'); if (voiceBar) { const container = voiceBar.closest('.voice-message-container'); if (container) container.classList.toggle('active'); return; }
                const pokeBubble = e.target.closest('.poke-bubble'); if (pokeBubble) { container.classList.add('is-shaking'); setTimeout(() => container.classList.remove('is-shaking'), 500); }
            });

            stageBtn.addEventListener('click', stageUserTextMessage);
            textInput.addEventListener('keypress', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); stageUserTextMessage(); } });

            stagedMessagesDisplay.addEventListener('click', (e) => {
                const voiceBar = e.target.closest('.voice-bar');
                if (voiceBar) { const container = voiceBar.closest('.voice-message-container'); if (container) container.classList.toggle('active'); e.stopPropagation(); return; }

                if (e.target.classList.contains('delete-staged-msg-btn')) { 
                    const index = parseInt(e.target.dataset.index, 10); 
                    stagedMessages.splice(index, 1); 
                    persistState(); 
                    renderAllStagedMessages(); 
                    return; 
                }

                const clickedStagedMsg = e.target.closest('.message-staged');
                if (clickedStagedMsg) {
                    stagedMessagesDisplay.querySelectorAll('.message-staged.show-delete').forEach(el => {
                        if (el !== clickedStagedMsg) el.classList.remove('show-delete');
                    });
                    clickedStagedMsg.classList.toggle('show-delete');
                }
            });

            realSendBtn.addEventListener('click', () => sendStagedMessages());

            const stickerHandler = {
                init() {
                    this.renderAllStickers(); this.setupTabs(); this.setupAddPanel(); 
                    stickerMenuBtn.addEventListener('click', () => { actionMenu.style.display = 'none'; stickerPanel.classList.toggle('active'); });
                },
                createStickerItem(name, filename) { const url = StickerStorageManager.URL_PREFIX + filename; const item = document.createElement('div'); item.className = 'sticker-item'; item.innerHTML = `<img src=\"${url}\" alt=\"${name}\" title=\"${name}\">`; item.addEventListener('click', () => { stageMessage('sticker', { name: name, url: url }); stickerPanel.classList.remove('active'); }); item.addEventListener('contextmenu', async (e) => { e.preventDefault(); if (confirm(`删除表情 \"${name}\"?`)) { await StickerStorageManager.deleteSticker(name); this.renderAllStickers(); } }); return item; },
                async renderAllStickers() { const grid = container.querySelector('#all-stickers'); grid.innerHTML = ''; const stickers = await StickerStorageManager.getStickers(); for (const [name, filename] of Object.entries(stickers)) { grid.appendChild(this.createStickerItem(name, filename)); } },
                setupTabs() { container.querySelectorAll('.sticker-tab').forEach(tab => tab.addEventListener('click', () => { container.querySelectorAll('.sticker-tab, .sticker-grid, .sticker-add-panel').forEach(el => el.classList.remove('active')); const tabName = tab.dataset.tab; tab.classList.add('active'); container.querySelector(`#${tabName === 'add' ? 'add-sticker-panel' : 'all-stickers'}`).classList.add('active'); })); },
                setupAddPanel() { const urlInput = container.querySelector('#sticker-url-input'), nameInput = container.querySelector('#sticker-name-input'), preview = container.querySelector('#sticker-preview'); const updatePreview = () => { if (urlInput.value.trim()) preview.innerHTML = `<img src=\"${StickerStorageManager.URL_PREFIX + urlInput.value.trim()}\" style=\"max-width:100%;max-height:100%;\">`; }; urlInput.addEventListener('input', updatePreview);
                    container.querySelector('#add-sticker-btn').addEventListener('click', async () => { if (urlInput.value && nameInput.value) { await StickerStorageManager.addSticker(nameInput.value, urlInput.value); urlInput.value = ''; nameInput.value = ''; preview.innerHTML = ''; this.renderAllStickers(); container.querySelector('[data-tab=\"stickers\"]').click(); } });
                    container.querySelector('#cancel-add-sticker').addEventListener('click', () => { container.querySelector('[data-tab=\"stickers\"]').click(); });
                }
            };
            stickerHandler.init();

            function setupModal(button, overlay, onConfirm) { 
                if (!button || !overlay) return; 
                const modal = overlay.querySelector('.modal-box'); 
                const confirmBtn = modal.querySelector('.confirm'); 
                const cancelBtn = modal.querySelector('.cancel'); 
                button.addEventListener('click', () => { overlay.style.display = 'flex'; }); 
                cancelBtn.addEventListener('click', () => { overlay.style.display = 'none'; }); 
                overlay.addEventListener('click', (e) => { if (e.target === overlay) overlay.style.display = 'none'; }); 
                if(onConfirm) confirmBtn.addEventListener('click', () => onConfirm(modal, overlay)); 
            }
            setupModal(imageMenuBtn, imageModalOverlay, (modal, overlay) => { const textarea = modal.querySelector('.image-modal-textarea'); const desc = textarea.value.trim(); if (desc) { stageMessage('image', desc); textarea.value = ''; overlay.style.display = 'none'; actionMenu.style.display = 'none'; } });
            setupModal(voiceMenuBtn, voiceModalOverlay, (modal, overlay) => { const textarea = modal.querySelector('.voice-modal-textarea'); const desc = textarea.value.trim(); if (desc) { stageMessage('voice', desc); textarea.value = ''; overlay.style.display = 'none'; actionMenu.style.display = 'none';} });
            setupModal(locationMenuBtn, locationModalOverlay, (modal, overlay) => { const input = modal.querySelector('.location-modal-input'); const location = input.value.trim(); if (location) { stageMessage('location', location); input.value = ''; overlay.style.display = 'none'; actionMenu.style.display = 'none';} });
            // NEW: Setup for the group video call modal
            setupModal(groupVideoMenuBtn, groupVideoCallModalOverlay, (modal, overlay) => {
                sendStagedMessages(`发起群视频|${chatName}|目标:`);
                overlay.style.display = 'none';
                actionMenu.style.display = 'none';
            });

            plusBtn.addEventListener('click', () => { 
                stickerPanel.classList.remove('active');
                actionMenu.style.display = actionMenu.style.display === 'grid' ? 'none' : 'grid'; 
            });

            document.addEventListener('click', (e) => { 
                const isClickInsideModal = allModals.some(modal => modal.contains(e.target));
                if (!container.querySelector('.chat-input').contains(e.target) && !actionMenu.contains(e.target) && !stickerPanel.contains(e.target) && !isClickInsideModal) { 
                    actionMenu.style.display = 'none'; 
                    stickerPanel.classList.remove('active'); 
