        <div class="custom-prompt-overlay"><div class="custom-prompt-box"><p class="prompt-title">发布动态</p><textarea class="prompt-text-input" placeholder="分享新鲜事..."></textarea><input type="text" class="prompt-image-input" placeholder="图片描述 (可选)"/><div class="custom-prompt-buttons"><button class="prompt-cancel-btn">取消</button><button class="prompt-confirm-btn">确定</button></div></div></div>
