</div>
<script>
    setTimeout(() => {
        const container = document.querySelector('.phone-container:not([data-initialized])');
        if (!container) return;
        container.dataset.initialized = 'true';
        try {
            const pageOwnerFromTag = `$1`.trim();
            const pageOwnerName = `$4`.trim();
            const pageOwnerAvatarFile = `$2`.trim();
            const isMyOwnPage = pageOwnerFromTag.toLowerCase() === 'user' || pageOwnerFromTag === '{{user}}';

            const headerAvatar = container.querySelector('.header-avatar');
            if (isMyOwnPage) {
                headerAvatar.classList.add('user_avatar', 'avatar');
            } else {
                headerAvatar.style.backgroundImage = `url('https://files.catbox.moe/${pageOwnerAvatarFile}')`;
            }

            const feedContainer = container.querySelector('.moments-feed');
            // CORRECTION: Select existing buttons from the DOM
            const postBtn = container.querySelector('.camera-icon-btn');
            const sendUpdatesBtn = container.querySelector('.send-updates-btn');
            const promptOverlay = container.querySelector('.custom-prompt-overlay');
            const promptTitle = container.querySelector('.prompt-title');
            const promptTextInput = container.querySelector('.prompt-text-input');
            const promptImageInput = container.querySelector('.prompt-image-input');
            const promptConfirm = container.querySelector('.prompt-confirm-btn');
            const promptCancel = container.querySelector('.prompt-cancel-btn');
            let userActions = [];
            let currentAction = { type: null, postId: null, targetUser: null };
            let newPostIdCounter = 0;

            const updateSendButtonState = () => { if (userActions.length > 0) { sendUpdatesBtn.classList.add('has-updates'); } else { sendUpdatesBtn.classList.remove('has-updates'); } };

            function manageLikeAction(postId, isLiking, targetUser) {
                const action = isLiking ? '点赞' : '取消点赞';
                const oppositeAction = isLiking ? '取消点赞' : '点赞';
                const command = `朋友圈更新|目标:${targetUser}|操作:${action}|动态ID:${postId}|`;
                const oppositeCommand = `朋友圈更新|目标:${targetUser}|操作:${oppositeAction}|动态ID:${postId}|`;
                const oppositeIndex = userActions.indexOf(oppositeCommand);
                if (oppositeIndex > -1) { userActions.splice(oppositeIndex, 1); } 
                else { userActions.push(command); }
                updateSendButtonState();
            }

            function renderNewComment(postId, commentText) {
                const post = feedContainer.querySelector(`[data-post-id='${postId}']`);
                if (!post) return;
                let feedback = post.querySelector('.post-feedback');
                if (!feedback) { const postMain = post.querySelector('.post-main'); postMain.insertAdjacentHTML('beforeend', '<div class="post-feedback"><div class="post-comments"></div></div>'); feedback = post.querySelector('.post-feedback'); }
                let comments = feedback.querySelector('.post-comments');
                if (!comments) { feedback.insertAdjacentHTML('beforeend', '<div class="post-comments"></div>'); comments = feedback.querySelector('.post-comments'); }
                const newCommentHtml = `<div class="comment"><span class="commenter">你</span>: ${commentText}</div>`;
                comments.insertAdjacentHTML('beforeend', newCommentHtml);
            }

            function renderNewPost(textContent, imageDesc) {
                 newPostIdCounter++;
                 const newPostId = `new-${newPostIdCounter}`;
                 let imageHtml = '';
                 if(imageDesc) {
                    const randomBg = `https://source.unsplash.com/random/160x160?sig=${Math.random()}`;
                    imageHtml = `<div class="image-card" style="background-image: url('${randomBg}');"><div class="image-card-desc"><p>${imageDesc}</p></div></div>`;
                 }
                const postHtml = `
                <div class="moment-post" data-post-id="${newPostId}" data-post-owner="user">
                    <div class="post-avatar user_avatar avatar"></div>
                    <div class="post-main">
                        <div class="post-username">${pageOwnerName}</div>
                        <div class="post-content">${textContent}</div>
                        <div class="post-image-container">${imageHtml}</div>
                        <div class="post-meta"><span class="post-time">刚刚</span><div class="post-actions"><span class="action-like">♡</span><span class="action-comment"><svg viewBox="0 0 24 24"><path fill="currentColor" d="M9,22A1,1 0 0,1 8,21V18H4A2,2 0 0,1 2,16V4C2,2.89 2.9,2 4,2H20A2,2 0 0,1 22,4V16A2,2 0 0,1 20,18H13.9L10.2,21.71C10,21.9 9.75,22 9.5,22V22H9M10,16V19.08L13.08,16H20V4H4V16H10Z" /></svg></span></div></div>
                    </div>
                </div>`;
                feedContainer.insertAdjacentHTML('afterbegin', postHtml);
                const emptyDivider = container.querySelector('.empty-feed-divider');
                if (emptyDivider) emptyDivider.style.display = 'none';
            }

            function openPrompt(type, postId = null, targetUser = null) {
                currentAction = { type, postId, targetUser };
                // Prompt is part of phone-screen, so its position is correct.
                promptOverlay.style.display = 'flex';
                if (type === 'post') { 
                    promptTitle.textContent = '发布动态'; 
                    promptTextInput.placeholder = '分享新鲜事...';
                    promptTextInput.style.display = 'block';
                    promptImageInput.style.display = 'block';
                } else if (type === 'comment') { 
                    promptTitle.textContent = '发表评论';
                    promptTextInput.placeholder = '说点什么...'; 
                    promptTextInput.style.display = 'block';
                    promptImageInput.style.display = 'none';
                }
                promptTextInput.focus();
            }

            // CORRECTION: Append buttons to the SCROLLABLE container and add listener there.
            const momentsContainer = container.querySelector('.moments-container');
            momentsContainer.appendChild(postBtn);
            momentsContainer.appendChild(sendUpdatesBtn);

            momentsContainer.addEventListener('click', (e) => {
                const likeBtn = e.target.closest('.action-like');
                const commentBtn = e.target.closest('.action-comment');
                const imageCard = e.target.closest('.image-card');
                const cameraBtn = e.target.closest('.camera-icon-btn');
                const sendBtn = e.target.closest('.send-updates-btn');

                if (likeBtn) {
                    const post = likeBtn.closest('.moment-post');
                    const postId = post.dataset.postId;
                    const targetUser = post.dataset.postOwner;
                    likeBtn.classList.toggle('liked');
                    const isLiked = likeBtn.classList.contains('liked');
                    likeBtn.textContent = isLiked ? '♥' : '♡';
                    manageLikeAction(postId, isLiked, targetUser);
                }
                if (commentBtn) { const post = commentBtn.closest('.moment-post'); openPrompt('comment', post.dataset.postId, post.dataset.postOwner); }
                if (imageCard && !e.target.closest('.image-card-desc')) { imageCard.classList.toggle('show-desc'); }
                if (cameraBtn) { openPrompt('post'); }
                if (sendBtn) {
                    if (userActions.length > 0) {
                        const command = userActions.join('');
                        const safeCommand = command.replace(/\|/g, '\\|');
                        if (typeof triggerSlash === 'function') { triggerSlash(`/send ${safeCommand}|/trigger`); }
                        userActions = [];
                        updateSendButtonState();
                    }
                }
            });

            if (!isMyOwnPage) { postBtn.style.display = 'none'; }

            promptCancel.addEventListener('click', () => { promptOverlay.style.display = 'none'; promptTextInput.value = ''; promptImageInput.value = ''; });
            promptConfirm.addEventListener('click', () => {
                const textContent = promptTextInput.value.trim();
                const imageDesc = promptImageInput.value.trim();
                if (textContent || imageDesc) {
                    if (currentAction.type === 'post') {
                        const imagePart = imageDesc ? `|图片:<tp> ${imageDesc} </tp>` : '|图片:无';
                        userActions.push(`朋友圈更新|目标:user|操作:发动态|内容:${textContent}${imagePart}|`);
                        renderNewPost(textContent, imageDesc);
                    } else if (currentAction.type === 'comment') {
                        userActions.push(`朋友圈更新|目标:${currentAction.targetUser}|操作:评论|动态ID:${currentAction.postId}|内容:${textContent}|`);
                        renderNewComment(currentAction.postId, textContent);
                    }
                    updateSendButtonState();
                }
                promptOverlay.style.display = 'none';
                promptTextInput.value = '';
                promptImageInput.value = '';
            });

            const bgRaw = `$3`.trim();
            const bgContainer = container.querySelector('.header-bg');
            if (bgRaw && bgRaw !== '空白' && bgRaw !== '默认空白') { bgContainer.style.backgroundImage = `url('https://files.catbox.moe/${bgRaw}')`; }

            const dynamicsRaw = `$6`;
            function parseAndRenderDynamics(rawText, isUser, avatarFile) {
                const dynamicsRegex = /\[动态\]([\s\S]*?)\[\/动态\]/g;
                let dynamicsHtml = '';
                let match;
                let postIdCounter = 0;
                while ((match = dynamicsRegex.exec(rawText)) !== null) {
                    postIdCounter++;
                    const lines = match[1].trim().split(/\r?\n/).filter(line => line.trim() !== '');
                    let post = { content: '', image: '无', time: '', likes: '', commentsRaw: '' };
                    let currentField = null;
                    for (const line of lines) {
                        const trimmedLine = line.trim();
                        const fieldMatch = trimmedLine.match(/^(内容|图片|时间|点赞者|评论):(.*)/);
                        if (fieldMatch) {
                            currentField = { '内容': 'content', '图片': 'image', '时间': 'time', '点赞者': 'likes', '评论': 'commentsRaw' }[fieldMatch[1]];
                            post[currentField] = fieldMatch[2].trim();
                        } else if (currentField) {
                            post[currentField] += '\n' + trimmedLine;
                        }
                    }

                    const postAvatarHtml = isUser
                        ? `<div class="post-avatar user_avatar avatar"></div>`
                        : `<div class="post-avatar" style="background-image: url('https://files.catbox.moe/${avatarFile}')"></div>`;

                    const imageRenderRegex = /<tp>([\s\S]*?)<\/tp>/;
                    const imageMatch = post.image.match(imageRenderRegex);
                    let imageHtml = '';
                    if(imageMatch && imageMatch[1]) {
                        const imageDesc = imageMatch[1].trim().replace(/\n/g, '<br>');
                        const randomBg = `https://source.unsplash.com/random/160x160?sig=${Math.random()}`;
                        imageHtml = `<div class="image-card" style="background-image: url('${randomBg}');"><div class="image-card-desc"><p>${imageDesc}</p></div></div>`;
                    }

                    const isLikedByUser = post.likes.includes('[user]');
                    const cleanedLikes = post.likes.replace(/\[user\]/g, '').trim();
                    let likesText = cleanedLikes;
                    if (cleanedLikes) {
                        const likers = cleanedLikes.split(/,|，/);
                        if (likers.length > 6) { likesText = likers.slice(0, 5).join(', ') + ', ...'; }
                    }
                    const likesHtml = likesText ? `<div class="post-likes">♥ ${likesText}</div>` : '';

                    const commentRegex = /\[评论者\](.*?)\[\/评论者\](?:回复\[评论者\](.*?)\[\/评论者\])?说:\[(.*?)\]/gs;
                    let commentsHtml = '';
                    let cMatch;
                    while ((cMatch = commentRegex.exec(post.commentsRaw)) !== null) {
                        /* MODIFICATION #2: Clean commenter names to remove stray [user] tags */
                        let [__, c1, c2, text] = cMatch.map(s => s ? s.trim() : s);
                        if (c1) c1 = c1.replace(/\[user\]/g, '').trim();
                        if (c2) c2 = c2.replace(/\[user\]/g, '').trim();
                        if (c2) { commentsHtml += `<div class="comment"><span class="commenter">${c1}</span> 回复 <span class="commenter">${c2}</span>: ${text}</div>`; }
                        else { commentsHtml += `<div class="comment"><span class="commenter">${c1}</span>: ${text}</div>`; }
                    }
                    const postCommentsHtml = commentsHtml ? `<div class="post-comments">${commentsHtml}</div>` : '';
                    const feedbackHtml = (likesHtml || postCommentsHtml) ? `<div class="post-feedback">${likesHtml}${postCommentsHtml}</div>` : '';

                    const likeButtonHtml = isLikedByUser 
                        ? `<span class="action-like liked">♥</span>` 
                        : `<span class="action-like">♡</span>`;

                    const postOwnerIdentifier = isUser ? 'user' : pageOwnerName;

                    dynamicsHtml += `
                    <div class="moment-post" data-post-id="${postIdCounter}" data-post-owner="${postOwnerIdentifier}">
                        ${postAvatarHtml}
                        <div class="post-main">
                            <div class="post-username">${pageOwnerName}</div>
                            <div class="post-content">${post.content.replace(/\n/g, '<br>')}</div>
                            <div class="post-image-container">${imageHtml}</div>
                            <div class="post-meta"><span class="post-time">${post.time}</span><div class="post-actions">${likeButtonHtml}<span class="action-comment"><svg viewBox="0 0 24 24"><path fill="currentColor" d="M9,22A1,1 0 0,1 8,21V18H4A2,2 0 0,1 2,16V4C2,2.89 2.9,2 4,2H20A2,2 0 0,1 22,4V16A2,2 0 0,1 20,18H13.9L10.2,21.71C10,21.9 9.75,22 9.5,22V22H9M10,16V19.08L13.08,16H20V4H4V16H10Z" /></svg></span></div></div>
                            ${feedbackHtml}
                        </div>
                    </div>`;
                }

                return dynamicsHtml;
            }
            feedContainer.innerHTML = parseAndRenderDynamics(dynamicsRaw, isMyOwnPage, pageOwnerAvatarFile);

            const emptyDivider = container.querySelector('.empty-feed-divider');
            if (feedContainer.children.length === 0) {
                emptyDivider.style.display = 'block';
            }

        } catch (error) {
            console.error('朋友圈脚本执行失败:', error);
            const feedContainer = document.querySelector('.moments-feed');
            if(feedContainer) feedContainer.innerHTML = `<div style='padding:20px; text-align:center; color: #999;'>朋友圈加载失败...<br><small>${error.message}</small></div>`;
        }
    }, 100);
</script>
</body>
</html>
