<script>
let timerInterval, seconds = 0, currentParticipants = [];
let groupName = `$1`;

function parseAndRenderParticipants(participantsString) {
    const grid = document.getElementById('participantGrid'); if (!grid) return;
    grid.innerHTML = '';
    try {
        const participantMatches = participantsString.trim().match(/\s*\[(.*?)(?:,(.*?))?\]/g);
        if (!participantMatches) throw new Error('Invalid participant format');
        currentParticipants = participantMatches.map(match => {
            const parts = match.replace(/\s*[\[\]]\s*/g, '').split(',');
            return { name: (parts[0] || '').trim(), avatar: (parts[1] || '').trim() };
        });
    } catch (e) { console.error('Failed to parse participants:', e); return; }
    const total = currentParticipants.length, maxToShow = 3;
    const visibleParticipants = currentParticipants.slice(0, maxToShow);
    visibleParticipants.forEach(p => {
        const item = document.createElement('div');
        const nameplate = document.createElement('div'); nameplate.className = 'participant-name'; nameplate.textContent = p.name;
        item.className = p.avatar ? 'participant-item' : 'participant-item user_avatar avatar';
        if (p.avatar) item.style.backgroundImage = `url('https://files.catbox.moe/${p.avatar}')`;
        item.appendChild(nameplate); grid.appendChild(item);
    });
    if (total > maxToShow) {
        const moreItem = document.createElement('div');
        moreItem.className = 'participant-item more-participants'; moreItem.textContent = `+${total - maxToShow}`;
        grid.appendChild(moreItem);
    }
}

function setDynamicBackground() {
    const userAvatarElement = document.querySelector('.participant-item.user_avatar');
    if (userAvatarElement) {
        const bgImage = window.getComputedStyle(userAvatarElement).backgroundImage;
        if (bgImage && bgImage !== 'none') document.getElementById('phoneContainer').style.backgroundImage = bgImage;
    }
}

function confirmInput() {
    const text = document.getElementById('videoInput').value.trim();
    if (text && typeof triggerSlash === 'function') {
        const targetNames = currentParticipants.filter(p => p.avatar).map(p => p.name).join(',');
        // FIXED: Escaped the '|' character for SillyTavern compatibility.
        const command = `继续群视频\\|群名称：${groupName}\\|目标:${targetNames}\\|内容:${text}`;
        triggerSlash(`/send ${command}|/trigger`);
    }
    hideInputModal(); document.getElementById('videoInput').value = '';
}

// --- Utility Functions ---
function updateTimer() { seconds++; const m = Math.floor(seconds / 60); const s = seconds % 60; document.getElementById('timer').textContent = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`; }
function updateStatusTime() { const now = new Date(); document.getElementById('status-time').textContent = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`; }
function startTimers() { if (!timerInterval) timerInterval = setInterval(updateTimer, 1000); updateStatusTime(); setInterval(updateStatusTime, 30000); }
function endCall() { clearInterval(timerInterval); if (typeof triggerSlash === 'function') triggerSlash(`/send [挂断群视频]|/trigger`); }
function showInputModal() { document.getElementById('videoModalOverlay').style.display = 'flex'; document.getElementById('videoInput').focus(); }
function hideInputModal() { document.getElementById('videoModalOverlay').style.display = 'none'; }

document.addEventListener('DOMContentLoaded', () => {
    startTimers();
    const participantsData = `$2`;
    parseAndRenderParticipants(participantsData);
    document.getElementById('groupNameTitle').textContent = `${groupName} (${currentParticipants.length})`;
    setTimeout(setDynamicBackground, 50);
    document.querySelector('.reply-call').addEventListener('click', showInputModal);
    document.querySelector('.end-call').addEventListener('click', endCall);
    const modal = document.getElementById('videoModalOverlay');
    modal.querySelector('.confirm').addEventListener('click', confirmInput);
    modal.querySelector('.cancel').addEventListener('click', hideInputModal);
});
</script>
