                    const allEraEntries = await this.getAllEraEntries();
                    if (allEraEntries.length === 0) {
                        // console.error("EraManager: 未找到任何时代条目，无法更新。");
                        let foundEras = this.ERA_COMMENTS.map(c => `备注为 ${c} 的条目`).join('、');
                        alert(`错误：未在世界书【${this.LOREBOOK_NAME}】中找到对应的时代条目。请检查是否已创建${foundEras}。`);
                        return false;
                    }

                    const entriesToUpdate = allEraEntries.map(entry => ({
                        uid: entry.uid,
                        enabled: entry.comment === enabledEraComment
                    }));

                    await setLorebookEntries(this.LOREBOOK_NAME, entriesToUpdate);
                    // console.log("EraManager: 成功更新时代条目状态。");
                    return true;
                } catch (error) {
                    // console.error("EraManager: 更新时代条目状态失败", error);
                    alert('更新时代背景失败，请按 F12 打开控制台查看日志。');
                    return false;
                }
            }
        };

        function updateButtonUI(button, isEnabled) {
            button.disabled = false;
            if (isEnabled) {
                button.textContent = '已选择';
                button.classList.add('enabled');
                button.classList.remove('disabled');
                button.disabled = true; 
            } else {
                button.textContent = '选择';
                button.classList.add('disabled');
                button.classList.remove('enabled');
            }
        }

        async function initializeEraControls() {
            const buttons = document.querySelectorAll('.era-toggle-btn');
            if (buttons.length === 0) return;

            const currentEraEntries = await EraManager.getAllEraEntries();

            buttons.forEach(btn => {
                const eraComment = btn.dataset.era;
                const correspondingEntry = currentEraEntries.find(e => e.comment === eraComment);

                if (correspondingEntry) {
                    updateButtonUI(btn, correspondingEntry.enabled);
                } else {
                    btn.textContent = '未找到';
                    btn.disabled = true;
                }

                btn.addEventListener('click', async function() {
                    if (this.classList.contains('enabled')) return;

                    buttons.forEach(b => {
                        b.disabled = true;
                        b.textContent = '处理中...';
                    });

                    await EraManager.updateEraStatuses(eraComment);

                    const latestEntries = await EraManager.getAllEraEntries();
                    buttons.forEach(b => {
                        const entry = latestEntries.find(e => e.comment === b.dataset.era);
                        if (entry) {
                            updateButtonUI(b, entry.enabled);
                        } else {
                            b.textContent = '错误';
                            b.disabled = true;
                        }
                    });
                });
            });
        }

        const choiceCards = document.querySelectorAll('.choice-card');
        choiceCards.forEach(card => {
            card.addEventListener('click', function() {
                const swipeId = parseInt(this.dataset.swipeId, 10);
                switchToNarrative(swipeId);
            });
        });

        async function switchToNarrative(swipeId) {
            const overlay = document.createElement('div');
            overlay.style.cssText = `
                position: fixed; top: 0; left: 0; width: 100%; height: 100%;
                background: rgba(255, 255, 255, 0.5); backdrop-filter: blur(10px);
                color: #3b3a50; font-size: 1.5rem; display: flex;
                justify-content: center; align-items: center; z-index: 10000;
                opacity: 0; transition: opacity 0.3s ease;
            `;
            overlay.textContent = '正在加载开场...';
            document.body.appendChild(overlay);
            requestAnimationFrame(() => overlay.style.opacity = '1');
            try {
                const messages = await getChatMessages(0, { include_swipe: true });
                if (Array.isArray(messages) && messages.length > 0 && messages[0].swipes && messages[0].swipes[swipeId] !== undefined) {
                    await setChatMessage(messages[0].swipes[swipeId], 0, {
                        swipe_id: swipeId,
                        refresh: 'display_and_render_current'
                    });
                } else {
                    throw new Error(`ID为 ${swipeId} 的开场白不存在。请确保你的第一个消息有足够多的刷卡选项以包含此ID`);
                }
            } catch (error) {
                // console.error("切换开场白失败:", error);
                overlay.remove();
                alert("切换失败！请确保你在SillyTavern等支持环境中，并检查控制台错误信息。");
            }
        }

        initializeEraControls();

    }, 100);
</script>

