            async getEntry() { try { const entries = await getLorebookEntries(this.LOREBOOK_NAME); return entries.find(entry => entry.comment === this.ENTRY_COMMENT); } catch (e) { return null; } },
            async getAddresses() { const entry = await this.getEntry(); if (!entry || !entry.content) return []; const match = entry.content.match(this.TAG_REGEX); if (!match || !match[1]) return []; try { return JSON.parse(match[1].trim() || '[]'); } catch (e) { return []; } },
