<div class="phone-container">
    <div class="phone-notch"><div class="notch-sensor"></div><div class="notch-camera"></div><div class="notch-speaker"></div><div class="notch-sensor"></div></div>
    <div class="main-screen-container">
        <div class="phone-header"><h2 class="phone-header-title">订单详情</h2></div>
        <div class="view-container">
            <div id="order-details-content" class="scroll-content"></div>
            <div class="waimai-data-source" style="display:none;">$1</div>
        </div>
    </div>
</div>

<script>
    (() => {
        const wrapper = document.querySelector('.phone-container');
        if (!wrapper || wrapper.dataset.rendered) return;
        wrapper.dataset.rendered = 'true';

        const contentContainer = document.getElementById('order-details-content');
        const dataSource = wrapper.querySelector('.waimai-data-source');
        const dataBlock = dataSource.textContent;

        const isShopAccepted = Math.random() < 0.5;
        const riderPosition = Math.floor(Math.random() * 51) + 20; // Random position from 20% to 70%

        const extractBlock = (tagName, text) => { const regex = new RegExp(`\\[${tagName}\\]([\\s\\S]*?)\\[\\/${tagName}\\]`); const match = text.match(regex); return match ? match[1].trim() : ''; };
        const extractValue = (key, block) => { const regex = new RegExp("^" + key + "\\s*[:：]\\s*(.*)", "m"); const match = block.match(regex); return match ? match[1].trim() : ''; };
        const extractItems = (itemsBlock) => { if (!itemsBlock) return []; const itemChunks = itemsBlock.split('[菜品]').filter(s => s.trim()); return itemChunks.map(chunk => ({ name: extractValue('菜品名', chunk), quantity: extractValue('数量', chunk), price: extractValue('单价', chunk) || extractValue('小计', chunk) })); };

        const orderInfoBlock = extractBlock('订单信息', dataBlock), shippingInfoBlock = extractBlock('收货信息', dataBlock), itemsListBlock = extractBlock('菜品列表', dataBlock), feesBlock = extractBlock('费用明细', dataBlock);
        const orderData = { eta: extractValue('预计送达', orderInfoBlock), riderName: extractValue('骑手姓名', orderInfoBlock), riderPhone: extractValue('骑手电话', orderInfoBlock), shopName: extractValue('商家名', orderInfoBlock), orderNumber: extractValue('订单号', orderInfoBlock), orderTime: extractValue('下单时间', orderInfoBlock), remark: extractValue('备注', orderInfoBlock), address: extractValue('地址', shippingInfoBlock), recipientName: extractValue('收货人', shippingInfoBlock), recipientPhone: extractValue('联系电话', shippingInfoBlock), items: extractItems(itemsListBlock), deliveryFee: extractValue('配送费', feesBlock), total: extractValue('总计', feesBlock)};

        const statusText = isShopAccepted ? '商家已接单，美味正在制作中' : '下单成功，等待商家接单';
        const timelineItem2Active = isShopAccepted ? 'active' : '';

        const statusCardHtml = `<div class="detail-card status-card"><p class="status-text">${statusText}</p><p class="eta-text">预计 <span class="eta-time">${orderData.eta}</span> 送达</p><div class="status-timeline"><div class="timeline-item active"><div class="timeline-icon"><i class="fa-solid fa-check"></i></div><p class="timeline-text">订单已提交</p></div><div class="timeline-item ${timelineItem2Active}"><div class="timeline-icon"><i class="fa-solid fa-store"></i></div><p class="timeline-text">商家备货中</p></div><div class="timeline-item"><div class="timeline-icon"><i class="fa-solid fa-motorcycle"></i></div><p class="timeline-text">骑手配送中</p></div></div></div>`;

        const riderCardHtml = `<div class="detail-card rider-map-card"><div class="vertical-map-container"><div class="route-line"><div class="line"></div><div class="map-point start"></div><div class="map-point rider" style="top: ${riderPosition}%;"></div><div class="map-point end"></div></div><div class="route-info"><p><svg class="custom-icon"><use xlink:href="#icon-shop"></use></svg><strong>商家位置</strong></p><p style="color:#000;"><svg class="custom-icon"><use xlink:href="#icon-rider"></use></svg><strong>骑手位置</strong></p><p><svg class="custom-icon"><use xlink:href="#icon-home"></use></svg><strong>您的位置</strong></p></div></div><div class="rider-info"><div class="rider-details"><div class="rider-avatar"><svg class="custom-icon"><use xlink:href="#icon-user"></use></svg></div><div class="rider-name-phone"><p class="rider-name">骑手 ${orderData.riderName}</p><p class="rider-phone">${orderData.riderPhone}</p></div></div><button class="contact-rider-btn"><i class="fa-solid fa-phone"></i> 联系骑手</button></div></div>`;

        const itemsHtml = orderData.items.map(item => { return `<div class=\"item\"><div class=\"name-and-qty\"><span class=\"name\">${item.name}</span><span class=\"qty\">x ${item.quantity}</span></div><span class=\"price\">${item.price}</span></div>`; }).join('');

        const itemsCardHtml = `<div class="detail-card order-items-card"><p class="shop-name">${orderData.shopName}</p><div class="items-list-container">${itemsHtml}</div><div class="fee-row" style="padding-top: 10px; border-top: 1px solid #f0f0f0;"><span>配送费</span><span>${orderData.deliveryFee}</span></div><div class="fee-row total-row"><span>总计</span><span class="price">${orderData.total}</span></div></div>`;

        const detailsCardHtml = `<div class="detail-card order-details-card"><div class="detail-row"><span class="key">收货地址</span><span class="value">${orderData.address}</span></div><div class="detail-row"><span class="key">收货人</span><span class="value">${orderData.recipientName}</span></div><div class="detail-row"><span class="key">联系方式</span><span class="value">${orderData.recipientPhone}</span></div><hr style="border:none; border-top: 1px solid #f0f0f0; margin: 8px 0"><div class="detail-row"><span class="key">订单号</span><span class="value">${orderData.orderNumber}</span></div><div class="detail-row"><span class="key">下单时间</span><span class="value">${orderData.orderTime}</span></div><div class="detail-row"><span class="key">备注</span><span class="value">${orderData.remark || '无'}</span></div></div>`;

        contentContainer.innerHTML = statusCardHtml + riderCardHtml + itemsCardHtml + detailsCardHtml;
        dataSource.remove();

    })();
</script>
</body>
</html>
