                }
            };
            const goBack = () => { if (viewHistory.length <= 1) return; viewHistory.pop(); const prevView = viewHistory[viewHistory.length - 1]; navigateTo(prevView, currentProductId); };

            // --- View Rendering ---
            const renderListView = () => { 
                productListContainer.innerHTML = productsData.map(p => `
                <div class="product-card-tb" data-id="${p.id}">
                    <div class="product-image-container-tb"><img src="${p.image}" class="product-image-tb" alt="${p.name}" loading="lazy"></div>
