                            <div class="product-sales-tb">月销 ${p.sales.replace('人付款','')}</div>
                        </div>
                        <div class="product-shop-name-tb">${p.shop}</div>
                    </div>
                </div>`).join('');
                $$('.product-card-tb').forEach(card => card.addEventListener('click', () => navigateTo('detail', parseInt(card.dataset.id, 10)))); 
            };

            const renderDetailView = (id) => { 
                const p = productsData.find(prod => prod.id === id); 
                if (!p) return; 
                productDetailContainer.innerHTML = `<div class="detail-image-container-tb"><img src="${p.image}" class="detail-image-tb" alt="${p.name}"></div><div class="detail-header-tb"><div class="detail-price-tb"><span>￥</span>${p.price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</div><div class="detail-title-tb">${p.name}</div><div class="detail-sales-shipping-tb"><span>${p.sales}</span><span>${p.shipping}</span><span>${p.location}</span></div></div><div class="detail-section-tb"><div class="detail-shop-tb"><i class="fa-solid fa-store"></i> <span>${p.shop}</span></div></div>${p.intro ? `<div class="detail-section-tb"><h3 class="detail-section-title-tb">商品详情</h3><p class="detail-intro-tb">${p.intro.replace(/\n/g, '<br>')}</p></div>` : ''}${p.reviews.length > 0 ? `<div class="detail-section-tb"><h3 class="detail-section-title-tb">宝贝评价</h3>${p.reviews.map(r => `<div class="review-card-tb"><div class="review-header-tb"><span class="review-author-tb">${r.author}</span></div><p class="review-content-tb">${r.content}</p></div>`).join('')}</div>` : ''}`; 
                productDetailContainer.scrollTop = 0; 
            };

            const renderCartView = () => { const hasItems = cartItems.length > 0; $('.cart-view-tb .cart-footer-tb').style.display = hasItems ? 'flex' : 'none'; manageCartBtn.style.display = hasItems ? 'inline-block' : 'none'; if (!hasItems) { cartItemsContainer.innerHTML = `<p class="cart-empty-message">购物车还是空的，快去逛逛吧~</p>`; toggleCartManageMode(false, true); return; } cartItemsContainer.innerHTML = cartItems.map(item => { const product = productsData.find(p => p.id === item.productId); return `<div class="cart-item-tb" data-product-id="${product.id}"><input type="checkbox" class="cart-item-checkbox" data-id="${product.id}" ${item.selected ? 'checked' : ''}><div class="cart-item-image-tb"><img src="${product.image}" alt="${product.name}"></div><div class="cart-item-details"><div class="cart-item-title">${product.name}</div><div class="cart-item-pricing-controls"><div class="cart-item-price">${formatPrice(product.price)}</div><div class="quantity-controls-tb"><button class="quantity-btn-tb minus">-</button><span class="quantity-display-tb">${item.quantity}</span><button class="quantity-btn-tb plus">+</button></div></div></div></div>`; }).join(''); addCartEventListeners(); updateCartSummary(); toggleCartManageMode(isCartInManageMode, true); };

            const updateCartSummary = () => { let totalPrice = 0, selectedCount = 0; cartItems.forEach(item => { if(item.selected){ const product = productsData.find(p => p.id === item.productId); totalPrice += product.price * item.quantity; selectedCount++; } }); $('.total-amount').textContent = formatPrice(totalPrice); $('.cart-checkout-btn-tb').textContent = `结算 (${selectedCount})`; $('.cart-delete-btn-tb').textContent = `删除 (${selectedCount})`; $('#select-all-checkbox').checked = cartItems.length > 0 && cartItems.every(item => item.selected); };
            const toggleCartManageMode = (manage, forceUpdate = false) => { if (isCartInManageMode === manage && !forceUpdate) return; isCartInManageMode = manage; manageCartBtn.textContent = isCartInManageMode ? '完成' : '管理'; $('.cart-checkout-btn-tb').style.display = isCartInManageMode ? 'none' : 'inline-block'; $('.cart-delete-btn-tb').style.display = isCartInManageMode ? 'inline-block' : 'none'; $('.cart-total-price-tb').style.visibility = isCartInManageMode ? 'hidden' : 'visible'; };

            const renderCheckoutView = async () => {
