        .custom-modal-overlay.show { opacity: 1; pointer-events: auto; }
        .custom-modal-tb { background: #fff; border-radius: 12px; padding: 24px; width: 280px; text-align: center; box-shadow: 0 5px 20px rgba(0,0,0,0.15); transform: scale(0.9); transition: transform 0.2s; }
        .custom-modal-overlay.show .custom-modal-tb { transform: scale(1); }
        .modal-message-tb { font-size: 16px; color: #333; margin-bottom: 24px; line-height: 1.5; }
        .modal-buttons-tb { display: flex; gap: 12px; }
        .modal-btn-tb { flex: 1; padding: 10px; border-radius: 8px; border: 1px solid #ddd; background: #fff; font-size: 15px; font-weight: 500; cursor: pointer; }
        .modal-btn-tb.modal-confirm-btn-tb { background: #FF5000; color: #fff; border-color: #FF5000; }
