<body>
    <div class="phone-container">
        <div class="phone-notch">
            <div class="notch-sensor"></div>
            <div class="notch-camera"></div>
            <div class="notch-speaker"></div>
            <div class="notch-sensor"></div>
        </div>
        <div class="main-screen-container" id="shopping-wrapper">
            <div class="phone-header">
                <div class="header-side left">
                     <button class="back-button-tb" style="display: none;"><i class="fa-solid fa-chevron-left"></i></button>
                </div>
                <h2 class="phone-header-title">购物广场</h2>
                <div class="header-side right">
                    <button class="header-cart-icon-tb" style="display: none;">
                        <i class="fa-solid fa-cart-shopping"></i>
