                    <button class="cart-manage-btn-tb" style="display: none;">管理</button>
                </div>
            </div>
            <div class="shopping-container-tb">
                <div id="list-view" class="view-container-tb active">
                    <div class="shopping-scroll-content-tb"><div class="product-list-tb" id="product-list"></div></div>
                </div>
