            </div>

            <div class="shopping-data-source" style="display:none;">$1</div>

            <!-- Address Panels -->
            <div id="address-panel-overlay" class="address-panel-overlay-tb">
                <div class="address-panel-tb">
                    <div class="address-panel-header-tb"><h3 class="address-panel-title-tb">选择收货地址</h3><button class="address-panel-close-tb"><i class="fa-solid fa-times"></i></button></div>
                    <div class="address-list-container-tb">
                        <div class="address-list-tb"></div>
                        <div class="address-panel-footer-tb"><button class="add-address-btn-tb"><i class="fa-solid fa-plus"></i> 新增收货地址</button></div>
                    </div>
