            <div id="address-action-sheet-overlay" class="address-action-sheet-overlay-tb">
                <div class="address-action-sheet-tb">
                    <div class="action-group"><button class="edit">编辑</button><button class="delete">删除</button></div>
                    <div class="cancel-group"><button class="cancel">取消</button></div>
                </div>
            </div>

            <!-- Custom UI Elements -->
            <div class="custom-toast-tb"></div>
            <div class="custom-modal-overlay">
                <div class="custom-modal-tb">
                    <p class="modal-message-tb"></p>
                    <div class="modal-buttons-tb">
                        <button class="modal-btn-tb modal-cancel-btn-tb"></button>
                        <button class="modal-btn-tb modal-confirm-btn-tb"></button>
                    </div>
                </div>
            </div>

        </div>
    </div>

    <script>
        (() => {
            const wrapper = document.getElementById('shopping-wrapper');
            if (!wrapper || wrapper.dataset.rendered) return;
            wrapper.dataset.rendered = 'true';

            // --- Lorebook Address Manager ---
            const AddressManager = { LOREBOOK_NAME: "关于霖大附中不得不说的那些事", ENTRY_COMMENT: "用户地址列表（不需要开启）", TAG_REGEX: /<用户地址列表>([\s\S]*?)<\/用户地址列表>/, async getEntry() { try { const entries = await getLorebookEntries(this.LOREBOOK_NAME); return entries.find(entry => entry.comment === this.ENTRY_COMMENT); } catch (e) { console.error("[购物平台] Lorebook查询失败:", e); return null; } }, async getAddresses() { const entry = await this.getEntry(); if (!entry || !entry.content) return []; const match = entry.content.match(this.TAG_REGEX); if (!match || !match[1]) return []; try { return JSON.parse(match[1].trim() || '[]'); } catch (e) { return []; } }, async saveAddresses(addresses) { const entry = await this.getEntry(); if (!entry) return false; const newContent = `<用户地址列表>\n${JSON.stringify(addresses, null, 2)}\n</用户地址列表>`; let finalContent = this.TAG_REGEX.test(entry.content) ? entry.content.replace(this.TAG_REGEX, newContent) : `${entry.content.trim()}\n\n${newContent}`; try { await setLorebookEntries(this.LOREBOOK_NAME, [{ uid: entry.uid, content: finalContent }]); return true; } catch (e) { return false; } }, async addAddress(address) { const addresses = await this.getAddresses(); address.id = `addr_${new Date().getTime()}`; addresses.push(address); return this.saveAddresses(addresses); }, async updateAddress(updatedAddress) { const addresses = await this.getAddresses(); const index = addresses.findIndex(addr => addr.id === updatedAddress.id); if (index !== -1) { addresses[index] = updatedAddress; return this.saveAddresses(addresses); } return false; }, async deleteAddress(addressId) { let addresses = await this.getAddresses(); addresses = addresses.filter(addr => addr.id !== addressId); return this.saveAddresses(addresses); } };

            // --- DOM Selectors ---
            const $ = (selector, context = wrapper) => context.querySelector(selector);
            const $$ = (selector, context = wrapper) => context.querySelectorAll(selector);

            // --- UI Elements ---
            const dataSource = $('.shopping-data-source'), backButton = $('.back-button-tb'), headerTitle = $('.phone-header-title'), cartIcon = $('.header-cart-icon-tb'), manageCartBtn = $('.cart-manage-btn-tb'), cartBadge = $('.cart-badge-tb');
            const views = { list: $('#list-view'), detail: $('#detail-view'), cart: $('#cart-view'), checkout: $('#checkout-view') };
            const productListContainer = $('#product-list'), productDetailContainer = $('#product-detail-content'), cartItemsContainer = $('#cart-items-list'), checkoutContentContainer = $('#checkout-content-container');
            const toastElement = $('.custom-toast-tb'), modal = { overlay: $('.custom-modal-overlay'), msg: $('.modal-message-tb'), confirmBtn: $('.modal-confirm-btn-tb'), cancelBtn: $('.modal-cancel-btn-tb')};
            const addr = { overlay: $('#address-panel-overlay'), panel: $('#address-panel-overlay .address-panel-tb'), title: $('.address-panel-title-tb'), closeBtn: $('.address-panel-close-tb'), listContainer: $('.address-list-container-tb'), list: $('.address-list-tb'), addBtn: $('.add-address-btn-tb'), formContainer: $('.address-add-form-container-tb'), form: $('.address-add-form-tb'), saveBtn: $('.address-add-form-container-tb .save'), cancelBtn: $('.address-add-form-container-tb .cancel') };
            const actionSheet = { overlay: $('#address-action-sheet-overlay'), sheet: $('.address-action-sheet-tb'), editBtn: $('.address-action-sheet-tb .edit'), deleteBtn: $('.address-action-sheet-tb .delete'), cancelBtn: $('.address-action-sheet-tb .cancel-group .cancel') };

            // --- State Variables ---
            let productsData = [], cartItems = [], currentProductId = null, currentView = 'list', viewHistory = ['list'], isCartInManageMode = false, toastTimer, allAddresses = [], selectedAddress = null, longPressTimer;
            let checkoutItems = [];

            // --- Data Parsing & Utils ---
            const extractValue = (key, block, isMultiline = false) => {
                if (isMultiline) { const startTag = `[${key}]`, endTag = `[/${key}]`; const startIndex = block.indexOf(startTag), endIndex = block.indexOf(endTag); return (startIndex !== -1 && endIndex !== -1) ? block.substring(startIndex + startTag.length, endIndex).trim() : ''; }
                const regex = new RegExp(`^${key}:\\s*(.*)$`, 'm'); const match = block.match(regex); return match ? match[1].trim() : '';
            };
            const parseProducts = () => { productsData = dataSource.textContent.trim().split(/\s*(?=\[商品\])/).filter(s => s.trim().startsWith('[商品]')).map((block, index) => ({ id: index, name: extractValue('商品名', block), price: parseFloat(extractValue('价格', block).replace(/[^\d.]/g, '')) || 0, shop: extractValue('店铺名', block), sales: extractValue('付款人数', block), location: extractValue('发货地', block), shipping: extractValue('运费', block), tags: extractValue('标签', block).split(/[,，]/).map(t => t.trim()).filter(Boolean), intro: extractValue('商品简介', block, true), reviews: (extractValue('评价', block, true) || '').split(/\s*(?=\[评论\])/).filter(Boolean).map(item => ({ author: extractValue('评论人', item).replace('[评论]', ''), content: extractValue('内容', item) })) })); };
            const formatPrice = (price) => `￥${price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

            // --- UI & State Update Functions ---
            const showToast = (message) => { clearTimeout(toastTimer); toastElement.textContent = message; toastElement.classList.add('show'); toastTimer = setTimeout(() => { toastElement.classList.remove('show'); }, 1000); };
            const _showModal = (message, {confirmText, cancelText, onConfirm, onCancel}) => { modal.msg.innerHTML = message; modal.confirmBtn.textContent = confirmText || '确定'; modal.cancelBtn.textContent = cancelText || '取消'; modal.confirmBtn.style.display = confirmText !== null ? 'block' : 'none'; modal.cancelBtn.style.display = cancelText !== null ? 'block' : 'none'; modal.overlay.classList.add('show'); const cleanup = () => { modal.overlay.classList.remove('show'); }; modal.confirmBtn.onclick = () => { if(onConfirm) onConfirm(); cleanup(); }; modal.cancelBtn.onclick = () => { if(onCancel) onCancel(); cleanup(); }; };
            const showAlertModal = (message) => _showModal(message, { confirmText: '确定', cancelText: null });
            const showConfirmModal = (message, onConfirm, confirmText = '删除') => _showModal(message, { confirmText: confirmText, cancelText: '取消', onConfirm });

            // --- Navigation ---
            const navigateTo = (viewName, productId = null) => {
                if (viewHistory[viewHistory.length - 1] !== viewName) viewHistory.push(viewName);
                currentView = viewName;
                Object.values(views).forEach(v => v.classList.remove('active'));
                views[currentView].classList.add('active');
                backButton.style.display = viewHistory.length > 1 ? 'block' : 'none';
                const totalQuantity = cartItems.reduce((sum, item) => sum + item.quantity, 0);
                if (totalQuantity > 0 && viewName !== 'cart' && viewName !== 'checkout') {
                     cartBadge.textContent = totalQuantity > 99 ? '99+' : totalQuantity; cartBadge.classList.add('show'); cartIcon.style.display = 'inline-block';
                } else { cartBadge.classList.remove('show'); cartIcon.style.display = 'none'; }
                manageCartBtn.style.display = viewName === 'cart' && cartItems.length > 0 ? 'inline-block' : 'none';
                switch(viewName) {
                    case 'list': headerTitle.textContent = '购物广场'; break;
                    case 'detail': headerTitle.textContent = '商品详情'; if(productId !== null) { currentProductId = productId; renderDetailView(productId); } break;
                    case 'cart': headerTitle.textContent = '购物车'; renderCartView(); break;
                    case 'checkout': headerTitle.textContent = '确认订单'; renderCheckoutView(); break;
                }
            };
            const goBack = () => { if (viewHistory.length <= 1) return; viewHistory.pop(); const prevView = viewHistory[viewHistory.length - 1]; navigateTo(prevView, currentProductId); };

            // --- View Rendering ---
            const renderListView = () => { productListContainer.innerHTML = productsData.map(p => `<div class="product-card-tb" data-id="${p.id}"><div class="product-title-tb">${p.name}</div><div class="product-shop-tb">${p.shop}</div>${p.tags.length > 0 ? `<div class="product-tags-bar-tb">${p.tags.map(tag => `<div class="product-tag-tb">${tag}</div>`).join('')}</div>` : ''}<div class="product-bottom-bar-tb"><div class="product-price-tb"><span>￥</span>${p.price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</div><div class="product-sales-tb">${p.sales}</div></div></div>`).join(''); $$('.product-card-tb').forEach(card => card.addEventListener('click', () => navigateTo('detail', parseInt(card.dataset.id, 10)))); };

            /* --- MODIFICATION 1: Removed review count from the title --- */
            const renderDetailView = (id) => { 
                const p = productsData.find(prod => prod.id === id); 
                if (!p) return; 
                productDetailContainer.innerHTML = `<div class="detail-header-tb"><div class="detail-title-tb">${p.name}</div><div class="detail-price-tb"><span>￥</span>${p.price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</div><div class="detail-sales-shipping-tb"><span>${p.sales}</span><span>${p.shipping}</span><span>${p.location}</span></div></div><div class="detail-section-tb"><div class="detail-shop-tb"><i class="fa-solid fa-store"></i> <span>${p.shop}</span></div></div>${p.intro ? `<div class="detail-section-tb"><h3 class="detail-section-title-tb">商品详情</h3><p class="detail-intro-tb">${p.intro.replace(/\n/g, '<br>')}</p></div>` : ''}${p.reviews.length > 0 ? `<div class="detail-section-tb"><h3 class="detail-section-title-tb">宝贝评价</h3>${p.reviews.map(r => `<div class="review-card-tb"><div class="review-header-tb"><span class="review-author-tb">${r.author}</span></div><p class="review-content-tb">${r.content}</p></div>`).join('')}</div>` : ''}`;
                 productDetailContainer.scrollTop = 0; 
            };

            const renderCartView = () => { const hasItems = cartItems.length > 0; $('.cart-view-tb .cart-footer-tb').style.display = hasItems ? 'flex' : 'none'; manageCartBtn.style.display = hasItems ? 'inline-block' : 'none'; if (!hasItems) { cartItemsContainer.innerHTML = `<p class="cart-empty-message">购物车还是空的，快去逛逛吧~</p>`; toggleCartManageMode(false, true); return; } cartItemsContainer.innerHTML = cartItems.map(item => { const product = productsData.find(p => p.id === item.productId); return `<div class="cart-item-tb" data-product-id="${product.id}"><input type="checkbox" class="cart-item-checkbox" data-id="${product.id}" ${item.selected ? 'checked' : ''}><div class="cart-item-details"><div class="cart-item-title">${product.name}</div><div class="cart-item-pricing-controls"><div class="cart-item-price">${formatPrice(product.price)}</div><div class="quantity-controls-tb"><button class="quantity-btn-tb minus">-</button><span class="quantity-display-tb">${item.quantity}</span><button class="quantity-btn-tb plus">+</button></div></div></div></div>`; }).join(''); addCartEventListeners(); updateCartSummary(); toggleCartManageMode(isCartInManageMode, true); };
            const updateCartSummary = () => { let totalPrice = 0, selectedCount = 0; cartItems.forEach(item => { if(item.selected){ const product = productsData.find(p => p.id === item.productId); totalPrice += product.price * item.quantity; selectedCount++; } }); $('.total-amount').textContent = formatPrice(totalPrice); $('.cart-checkout-btn-tb').textContent = `结算 (${selectedCount})`; $('.cart-delete-btn-tb').textContent = `删除 (${selectedCount})`; $('#select-all-checkbox').checked = cartItems.length > 0 && cartItems.every(item => item.selected); };
            const toggleCartManageMode = (manage, forceUpdate = false) => { if (isCartInManageMode === manage && !forceUpdate) return; isCartInManageMode = manage; manageCartBtn.textContent = isCartInManageMode ? '完成' : '管理'; $('.cart-checkout-btn-tb').style.display = isCartInManageMode ? 'none' : 'inline-block'; $('.cart-delete-btn-tb').style.display = isCartInManageMode ? 'inline-block' : 'none'; $('.cart-total-price-tb').style.visibility = isCartInManageMode ? 'hidden' : 'visible'; };

            /* --- MODIFICATION 2: Reworked the checkout view rendering logic --- */
            const renderCheckoutView = async () => {
                allAddresses = await AddressManager.getAddresses();
                if (allAddresses.length > 0 && !selectedAddress) { selectedAddress = allAddresses[0]; }

                const itemsForCheckout = checkoutItems;
                let grandTotal = 0;

                const itemsByShop = itemsForCheckout.reduce((acc, item) => {
                    const product = productsData.find(p => p.id === item.productId);
                    if (product) {
                        if (!acc[product.shop]) { acc[product.shop] = []; }
                        acc[product.shop].push({ ...item, ...product });
                    }
                    return acc;
                }, {});

                const merchantsHtml = Object.entries(itemsByShop).map(([shopName, items]) => {
                    let shopSubtotal = 0;

                    /* --- Changed HTML structure of items list --- */
                    const itemsHtml = items.map(item => {
                        const itemTotal = item.price * item.quantity;
                        shopSubtotal += itemTotal;
                        return `
                        <div class="checkout-item">
                            <div class="product-info">
                                <div class="product-name">${item.name}</div>
                                <div class="product-price-details">
                                    <span class="product-quantity">x${item.quantity}</span>
                                    <span class="product-price">${formatPrice(itemTotal)}</span>
                                </div>
                            </div>
                        </div>`;
                    }).join('');

                    const subtotalHtml = `<div class="checkout-subtotal-row"><span class="label">商家小计</span><span class="amount">${formatPrice(shopSubtotal)}</span></div>`;
                    grandTotal += shopSubtotal;

                    return `<div class="checkout-card checkout-merchant-card">
                                <h4><i class="fa-solid fa-store"></i>${shopName}</h4>
                                ${itemsHtml}
                                ${subtotalHtml}
                            </div>`;
                }).join('');

                const addressHtml = selectedAddress ? `<div class="address-details-tb"><p class="address-location-tb">${selectedAddress.收货地址}</p><p class="address-contact-tb"><span>${selectedAddress.收货人}</span> <span>${selectedAddress.联系电话}</span>${selectedAddress.标签 ? `<span class="tag">${selectedAddress.标签}</span>` : ''}</p></div><i class="fa-solid fa-chevron-right address-chevron-tb"></i>` : `<div class="checkout-address-placeholder">点击选择或添加收货地址</div><i class="fa-solid fa-chevron-right address-chevron-tb"></i>`;

                checkoutContentContainer.innerHTML = `<div class="checkout-card checkout-address-card">${addressHtml}</div>${merchantsHtml}`;
                $('.checkout-footer-total-tb span').textContent = formatPrice(grandTotal);
                $('.checkout-address-card').addEventListener('click', showAddressPanel);
            };

            // --- Address Management UI --- 
            const showAddressPanel = async () => { toggleAddressForm(false); await renderAddressList(); addr.overlay.classList.add('active'); };
            const hideAddressPanel = () => { addr.overlay.classList.remove('active'); };
            const renderAddressList = async () => { allAddresses = await AddressManager.getAddresses(); if (!Array.isArray(allAddresses) || allAddresses.length === 0) { addr.list.innerHTML = '<p style="text-align:center; padding: 20px; color: #888;">还没有收货地址</p>'; return; }  addr.list.innerHTML = allAddresses.map(a => `<div class="address-item-tb" data-address-id="${a.id}"><i class="fa-solid fa-map-marker-alt address-item-icon-tb"></i><div class="address-details-tb"><p class="address-location-tb">${a.收货地址}</p><p class="address-contact-tb"><span>${a.收货人}</span> <span>${a.联系电话}</span>${a.标签 ? `<span class="tag">${a.标签}</span>` : ''}</p></div></div>`).join(''); $$('.address-item-tb').forEach(item => { const addressId = item.dataset.addressId; const showActions = (e) => { e.preventDefault(); clearTimeout(longPressTimer); showAddressActionSheet(addressId); }; item.addEventListener('click', () => { clearTimeout(longPressTimer); selectedAddress = allAddresses.find(a => a.id === addressId); hideAddressPanel(); renderCheckoutView(); }); item.addEventListener('contextmenu', showActions); item.addEventListener('touchstart', (e) => { longPressTimer = setTimeout(() => showActions(e), 700); }, { passive: true }); item.addEventListener('touchend', () => clearTimeout(longPressTimer)); item.addEventListener('touchmove', () => clearTimeout(longPressTimer)); }); };
