<script>
    (() => {
        // Utility function to extract key-value data from text blocks
        const extractValue = (key, block) => {
            const regex = new RegExp(`^${key}:\\s*(.*)$`, 'm');
            const match = block.match(regex);
            return match ? match[1].trim() : '';
        };

        // 1. Get data captured by regex from the hidden data source
        const orderId = document.getElementById('order-id').textContent.trim();
        const creationTime = document.getElementById('creation-time').textContent.trim(); // MODIFICATION: Get creation time from data source
        const shippingInfoBlock = document.getElementById('shipping-info').textContent.trim();
        const productsListBlock = document.getElementById('products-list').textContent.trim();
        const totalPrice = document.getElementById('total-price').textContent.trim();

        // 2. Parse the captured data into structured objects
        const shippingInfo = {
            address: extractValue('地址', shippingInfoBlock),
            recipient: extractValue('收货人', shippingInfoBlock),
            phone: extractValue('联系电话', shippingInfoBlock)
        };

        const productsByShop = productsListBlock
            .split(/\s*(?=\[商品\])/) // Split into individual item blocks
            .filter(s => s.trim().startsWith('[商品]'))
            .reduce((acc, block) => {
                const shopName = extractValue('店铺名', block);
                const product = {
                    name: extractValue('商品名', block),
                    quantity: parseInt(extractValue('数量', block), 10) || 1,
                    subtotal: extractValue('小计', block)
                };
                if (!acc[shopName]) {
                    acc[shopName] = [];
                }
                acc[shopName].push(product);
                return acc;
            }, {});

        // 3. Render the parsed data into the HTML structure
        // Render Address
        const addressContainer = document.getElementById('address-container');
        addressContainer.innerHTML = `
            <i class="fa-solid fa-map-marker-alt address-icon"></i>
            <div class="address-details">
                <p class="address-contact">${shippingInfo.recipient} ${shippingInfo.phone}</p>
                <p class="address-location">${shippingInfo.address}</p>
            </div>
        `;

        // Render Products
        const productsContainer = document.getElementById('products-container');
        let productsHtml = '';
        let shopSubtotal = 0;
        Object.keys(productsByShop).forEach(shopName => {
            const items = productsByShop[shopName];
            // MODIFICATION START: Updated HTML structure for product items
            const itemsHtml = items.map(p => {
                shopSubtotal += parseFloat(p.subtotal.replace(/[^\d.]/g, '')) || 0;
                return `
                <div class="product-item">
                    <div class="product-info">
                        <div class="product-name">${p.name}</div>
                        <div class="product-price-details">
                            <span class="product-quantity">x${p.quantity}</span>
                            <span class="product-price">${p.subtotal}</span>
                        </div>
                    </div>
                </div>
            `;}).join('');
            // MODIFICATION END

            productsHtml += `
                <div class="card">
                    <div class="shop-header">
                        <i class="fa-solid fa-store shop-icon"></i>
                        <span class="shop-name">${shopName}</span>
                    </div>
                    ${itemsHtml}
                </div>
            `;
        });
        productsContainer.innerHTML = productsHtml;

        // Render Summary
        const summaryContainer = document.getElementById('summary-container');
        summaryContainer.innerHTML = `
            <div class="summary-line">
                <span class="label">商品总价</span>
                <span class="value">${totalPrice}</span>
            </div>
            <div class="summary-line">
                <span class="label">运费</span>
                <span class="value">￥0.00</span>
            </div>
            <div class="summary-line total">
                <span class="label">订单总价</span>
                <span class="value">${totalPrice}</span>
            </div>
        `;

        // Render Order Info (MODIFICATION: Use the extracted creationTime)
        const orderInfoContainer = document.getElementById('order-info-container');
        // const creationTime = new Date().toLocaleString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }); // OLD CODE REMOVED
        orderInfoContainer.innerHTML = `
            <div>订单编号：<strong>${orderId}</strong></div>
            <div>创建时间：<strong>${creationTime}</strong></div>
        `;

        // 4. Cleanup the data source element
        document.getElementById('data-source').remove();
    })();
</script>
