    <div class="diary-container">
        <div class="diary-frame">
            <div class="diary-content" id="diary-content"></div>
            <div class="diary-nav" id="diary-nav">
                <button id="prev-page" class="nav-button">上一页</button>
                <div class="page-indicator"><span id="current-page-num">1</span> / <span id="total-pages">1</span></div>
                <button id="next-page" class="nav-button">下一页</button>
            </div>
        </div>
    </div>

    <script>
        const tagMappings = { gl: (c) => `<span class="glow-text">${c}</span>`, sk: (c) => `<span class="tape-tag">${c}</span>`, wu: (c) => `<span class="wavy-underline">${c}</span>`, sh: (c) => `<span class="bold-text">${c}</span>`, cr: (c) => `<span class="strikethrough-text">${c}</span>` };
        let allDiaryEntries = [], currentPageIndex = 0;
        function convertTagsToHtml(text) {
            let processedText = text;
            Object.entries(tagMappings).forEach(([tag, replacer]) => {
                const regex = new RegExp(`<${tag}>(.*?)<\/${tag}>`, 'gs');
                processedText = processedText.replace(regex, (_, content) => replacer(content));
            });
            return processedText.replace(/\\n/g, '<br>');
        }
        function parseDiaryText(fullText) {
            const entryRegex = /\[(\d{4}年\d{1,2}月\d{1,2}日\s*星期[一二三四五六日]?\s*｜[^｜]*?｜[^\]]*?)\]/g;
            const contentParts = fullText.split(entryRegex).slice(1);
            const entries = [];
            for (let i = 0; i < contentParts.length; i += 2) {
                const metaHeader = contentParts[i], contentText = contentParts[i + 1] || "";
                const metaParts = metaHeader.split('｜');
                if (metaParts.length < 3) continue;
                entries.push({ date: metaParts[0].trim(), mood: metaParts[1].trim(), weather: metaParts[2].trim(), content: contentText.trim() });
            }
            return entries;
        }
        function createDiaryEntryHTML(data) {
            const formattedContent = convertTagsToHtml(data.content);
            return `<div class="diary-entry"><div class="diary-header"><div class="diary-date">${data.date}</div><div class="diary-meta"><span>Mood: ${data.mood}</span><span>Weather: ${data.weather}</span></div></div><div class="diary-text">${formattedContent}</div></div>`;
        }
        function displayCurrentDiaryPage() {
            const contentEl = document.getElementById('diary-content');
            if (!allDiaryEntries || allDiaryEntries.length === 0) {
                contentEl.innerHTML = `<div class="diary-entry"><div class="diary-text" style="text-align: center; color: var(--text-meta);">未找到日记内容。<br>请在 ` + "`[日记]`" + `和` + "`[/日记]`" + `之间书写。</div></div>`;
                return;
            }
            const entry = allDiaryEntries[currentPageIndex];
            contentEl.innerHTML = entry ? createDiaryEntryHTML(entry) : '<p>日记加载失败</p>';
            contentEl.scrollTop = 0;
            updateNavigation();
        }
        function updateNavigation() {
            const navEl = document.getElementById('diary-nav'), totalPages = allDiaryEntries.length;
            if (totalPages > 1) {
                navEl.style.display = 'flex';
                document.getElementById('current-page-num').textContent = currentPageIndex + 1;
                document.getElementById('total-pages').textContent = totalPages;
                document.getElementById('prev-page').disabled = (currentPageIndex === 0);
                document.getElementById('next-page').disabled = (currentPageIndex >= totalPages - 1);
            } else { navEl.style.display = 'none'; }
        }
        function navigateTo(direction) {
            const newIndex = currentPageIndex + direction;
            if (newIndex >= 0 && newIndex < allDiaryEntries.length) { currentPageIndex = newIndex; displayCurrentDiaryPage(); }
        }
        function initialize() {
            const matchedDiaryContent = `$1`;
            const diaryText = matchedDiaryContent.trim();
            if (diaryText) { allDiaryEntries = parseDiaryText(diaryText); }
            displayCurrentDiaryPage();
            document.getElementById('prev-page').addEventListener('click', () => navigateTo(-1));
            document.getElementById('next-page').addEventListener('click', () => navigateTo(1));
        }
        initialize();
    </script>
</body>
